T("A Suite look, font, minimum height and position for Blizzard dialogs, marked resurrection offers, the item quality written on loot toasts and gold-framed money toasts.", "블리자드 대화 상자의 Suite 모양, 글꼴, 최소 높이와 위치, 표시된 부활 제안, 전리품 알림에 적힌 아이템 품질, 금색 테두리의 골드 알림.")
