T("A cinematic Suite screen with your character while you are AFK. Move or use /afk to return.", "AFK 상태일 때 캐릭터를 보여 주는 영화 같은 Suite 화면입니다. 움직이거나 /afk를 입력하면 돌아옵니다.")
T("A class in your group can provide this buff.", "파티 내 직업이 이 강화 효과를 제공할 수 있습니다.")
T("A clean minimap in its own frame: size, shape, border, zoom, Blizzard buttons, an addon button drawer and information texts. Blizzard's minimap buttons keep working.", "독립된 프레임에 표시되는 깔끔한 미니맵입니다: 크기, 모양, 테두리, 확대, 블리자드 버튼, 애드온 버튼 서랍, 정보 텍스트. 블리자드 미니맵 버튼은 그대로 작동합니다.")
T("A click-through surface follows each Blizzard chat window. Blizzard and MSUF Edit Mode keep their normal move and resize controls.", "클릭이 통과되는 표면이 각 블리자드 대화창을 따라갑니다. 블리자드 및 MSUF 편집 모드의 이동 및 크기 조절 기능은 그대로 유지됩니다.")
T("A colored plate sits behind the map and its border. Padding extends it beyond the map edge.", "지도와 테두리 뒤에 색상 판이 놓입니다. 여백을 늘리면 지도 가장자리 밖으로 확장됩니다.")
T("A compact clock, FPS and latency bar.", "시계, FPS와 지연 시간을 표시하는 작은 바입니다.")
T("A compact, movable history of your recent successful spells.", "최근 성공한 주문에 대한 이동 가능한 간략한 기록입니다.")
T("A frame-rate readout can sit below the strip or on its own, placed in MSUF Edit Mode. The MSUF Suite FPS key binding shows or hides it for this session, in combat too; a new choice here replaces that session switch.", "프레임 표시는 바 아래나 따로 둘 수 있으며 MSUF 편집 모드에서 배치합니다. MSUF Suite FPS 단축키는 이번 세션 동안 전투 중에도 표시를 켜거나 끄며, 여기서 새로 고르면 그 세션 설정을 대신합니다.")
T("A movable strip for critical strike, haste, mastery and versatility.", "치명타, 가속, 특화, 유연성을 표시하는 이동 가능한 작은 표시줄입니다.")
T("A movable summary after a Mythic+ run or raid boss kill.", "신화+ 공략 또는 공격대 우두머리 처치 후 표시되는 이동 가능한 요약입니다.")
T("A ring around the mouse pointer that is easy to spot, optionally filled by your global cooldown or cast.", "마우스 포인터를 쉽게 찾게 해 주는 고리로, 전역 재사용 대기시간이나 시전으로 채울 수 있습니다.")
T("A ring around the mouse pointer that makes it easy to find. Pick its shape, size, color, an optional short trail and a centre dot; No ring keeps only the dot or the progress fill. The camera mode shows ring, dot and trail only while you hold a mouse button down on the game world to turn the camera. The highlight follows the pointer only while something is shown, and it moves nothing while the pointer rests.", "마우스 포인터를 쉽게 찾도록 주위에 고리를 표시합니다. 모양, 크기, 색상, 짧은 잔상과 중심 점을 고를 수 있으며, '고리 없음'은 점이나 진행 채움만 남깁니다. 카메라 모드는 게임 월드에서 마우스 버튼을 눌러 카메라를 돌리는 동안에만 고리, 점, 잔상을 표시합니다. 강조 표시는 무언가 보일 때만 포인터를 따라가며, 포인터가 멈춰 있으면 아무것도 움직이지 않습니다.")
T("A small summary sits beside the Character tab of your character sheet and leaves with it. It lists your gear with gem sockets and how many are filled, open ones in amber (click a line to open socketing), the total durability of your gear and, if you like, your PvP item level. Its buttons open the Great Vault and the current expansion page. It updates while the sheet is open, at most once per frame.", "작은 요약이 캐릭터 창의 캐릭터 탭 옆에 있으며 탭과 함께 사라집니다. 보석 홈이 있는 장비와 채워진 개수를 보여주며 빈 홈은 호박색으로 표시합니다(줄을 클릭하면 보석 장착 창이 열립니다). 장비의 전체 내구도와 원하면 PvP 아이템 레벨도 표시합니다. 버튼으로 위대한 금고와 현재 확장팩 페이지를 엽니다. 창이 열려 있는 동안 최대 프레임당 한 번 갱신됩니다.")
T("A soft light behind the map, independent of the border and artwork.", "테두리 및 아트워크와 별개로 지도 뒤에 은은한 빛을 비춥니다.")
T("A summary with gem sockets, durability, PvP item level and Great Vault and expansion buttons, durability on the model, cropped slot icons and item levels on equipment choices.", "보석 홈, 내구도, PvP 아이템 레벨과 위대한 금고 및 확장팩 버튼이 있는 요약, 모델 위 내구도, 잘라낸 슬롯 아이콘, 장비 선택의 아이템 레벨.")
