T("Accept only ordinary party invitations from the relationship types you select. Invites remain manual in combat, while grouped, during queue-loss or quest-session confirmations, or when Blizzard asks you to choose a role. The native popup handles the final action.", "선택한 관계의 일반 파티 초대만 자동 수락합니다. 전투 중, 이미 파티에 속한 경우, 대기열을 잃거나 퀘스트 세션을 확인해야 하는 경우, 블리자드가 역할 선택을 요청하는 경우에는 직접 수락해야 합니다. 최종 동작은 블리자드 기본 팝업이 처리합니다.")
