T("Adds automatic collection on top of Blizzard's own Auto Loot setting, which stays unchanged. Locked slots and confirmations stay manual.", "블리자드 자체 자동 전리품 획득 설정은 그대로 두고 자동 획득 기능을 추가합니다. 잠긴 칸과 확인 창은 수동으로 처리합니다.")
T("Adds guild rank, the hovered unit's target, item levels, the unit's current mount and item or spell details to Blizzard's main tooltip, and can show player names without titles. Your own item level and the one of the unit open in the Inspect window need no request. Item levels of other hovered players are a separate choice that sends inspect requests: at most one per hover, never while the Inspect window or another inspect is busy. Mounts are read once when a unit tooltip opens, out of combat; a change appears on the next hover. Place the fixed corner in MSUF Edit Mode; the cursor offsets apply to the cursor anchor.", "블리자드 기본 툴팁에 길드 등급, 유닛의 대상, 아이템 레벨, 유닛의 현재 탈것, 아이템이나 주문 정보를 추가하고 플레이어 이름을 칭호 없이 표시할 수 있습니다. 자신의 아이템 레벨과 살펴보기 창에 열린 유닛의 아이템 레벨에는 요청이 필요 없습니다. 마우스를 올린 다른 플레이어의 아이템 레벨은 살펴보기 요청을 보내는 별도 옵션입니다. 마우스를 올릴 때마다 최대 한 번만 요청하며, 살펴보기 창이나 다른 살펴보기가 진행 중일 때는 요청하지 않습니다. 탈것은 전투 밖에서 유닛 툴팁이 열릴 때 한 번 읽으며, 변경 사항은 다음에 마우스를 올릴 때 나타납니다. 고정 모서리는 MSUF 편집 모드에서 배치하며, 커서 오프셋은 커서 고정에 적용됩니다.")
T("Adds the current-season Mythic+ score to the main tooltip of another player when Blizzard provides a public score. Unknown or restricted scores stay hidden.", "블리자드가 공개 점수를 제공할 때 다른 플레이어의 기본 툴팁에 현재 시즌 신화+ 점수를 추가합니다. 알 수 없거나 제한된 점수는 숨겨져 있습니다.")
T("Adjust the glass effect while keeping your colors and window coverage.", "색상과 창 적용 범위는 유지하면서 유리 효과를 조정합니다.")
T("Adventure Guide", "모험 가이드")
T("After a completed Mythic+ run or successful raid encounter, show the public result values in a separate card. Choose which figures appear and how long the card stays open. The last result can be reopened here. Combat delays the card until it is safe to show.", "신화+ 공략 완료 또는 공격대 전투 승리 후 공개된 결과 값을 별도 카드에 표시합니다. 표시할 수치와 카드 유지 시간을 선택합니다. 여기서 마지막 결과를 다시 열 수 있습니다. 전투 중에는 안전하게 표시할 수 있을 때까지 카드를 미룹니다.")
T("After closing the chest loot", "상자 전리품 창을 닫은 후")
