T("An adjacent button opens a small menu for expansion, Great Vault, Adventure Guide and world map pages. Blizzard's landing button keeps its own click behavior. Menu actions are disabled in combat.", "옆의 버튼을 누르면 확장팩, 위대한 금고, 모험 안내서, 세계 지도 화면을 여는 작은 메뉴가 표시됩니다. 블리자드의 기존 버튼은 원래 클릭 동작을 유지합니다. 전투 중에는 메뉴 동작을 사용할 수 없습니다.")
T("An empty allow-list includes every quest. Separate quest IDs with spaces or commas. Daily and weekly exclusions leave a quest manual if its frequency cannot be read. Existing profiles keep their previous behavior until you enable an exclusion.", "허용 목록이 비어 있으면 모든 퀘스트가 포함됩니다. 퀘스트 ID는 공백이나 쉼표로 구분하세요. 일일 및 주간 제외 설정은 퀘스트의 반복 주기를 읽을 수 없으면 해당 퀘스트를 수동으로 남겨 둡니다. 기존 프로필은 제외 설정을 켤 때까지 이전 동작을 유지합니다.")
