T("Blizzard Edit Mode owns position. The Suite keeps its button plates and Blizzard supplies only the icons.", "위치는 블리자드 편집 모드가 관리합니다. Suite는 버튼 배경판을 유지하고 블리자드는 아이콘만 제공합니다.")
