T("Blizzard keeps every original font size and style flag.", "블리자드는 원래 글꼴 크기와 스타일 플래그를 모두 유지합니다.")
T("Blizzard keeps its text sizes and outlines.", "블리자드는 텍스트 크기와 외곽선을 그대로 유지합니다.")
T("Blizzard keeps the button artwork, clicks, tooltips, enabled states and notifications. Optional glyph artwork is available in the detail controls. Visual changes apply outside combat only.", "버튼 아트워크, 클릭, 툴팁, 활성 상태, 알림은 블리자드가 그대로 유지합니다. 선택형 기호 아트워크는 세부 설정에서 사용할 수 있습니다. 시각적 변경은 전투 중이 아닐 때만 적용됩니다.")
T("Blizzard layout captured", "블리자드 배치 저장됨")
T("Blizzard layout imported", "블리자드 배치 가져옴")
T("Blizzard original", "블리자드 원본")
T("Blizzard owns aggro flashes, progressive highlights and soft target icons. Optional colors tint Blizzard's existing threat textures; its health bar threat color stays under the role-color overlay. Soft target icons also need the nameplate icon switch enabled and a matching soft target in game.", "어그로 점멸, 점진적 강조, 약한 대상 지정 아이콘은 블리자드가 관리합니다. 선택한 색상은 기존 위협 수준 텍스처에 적용되며, 생명력 막대의 위협 색상은 역할 색상 아래에 유지됩니다. 약한 대상 지정 아이콘을 보려면 이름표 아이콘 설정을 켜고 게임에서 해당 대상이 지정되어야 합니다.")
T("Blizzard owns the aura icons and updates. Choose Keep Blizzard setting or Customize for each unit type. Buffs, debuffs and control effects can be selected and dragged separately in the preview. Aura size uses Blizzard's own setting.", "오라 아이콘과 갱신은 블리자드가 처리합니다. 유닛 유형마다 '블리자드 설정 유지' 또는 '사용자 지정'을 선택하세요. 미리보기에서 강화 효과, 약화 효과, 제어 효과를 각각 선택하고 끌 수 있습니다. 오라 크기는 블리자드 자체 설정을 따릅니다.")
T("Blizzard owns these elements. The rarity icon setting applies to all nameplates; raid target icons are hidden only on enemy plates. Castbar details control Blizzard's own castbar. The preview and live plates use the same switches.", "이 요소들은 블리자드가 처리합니다. 희귀도 아이콘 설정은 모든 이름표에 적용되며, 공격대 대상 아이콘은 적 이름표에서만 숨겨집니다. 시전 바 세부 정보는 블리자드 자체 시전 바를 제어합니다. 미리보기와 실제 이름표는 같은 스위치를 사용합니다.")
T("Blizzard personal auras", "블리자드 개인 오라")
T("Blizzard plate size (health bar + elements)", "블리자드 이름표 크기 (생명력 바 + 요소)")
T("Blizzard plate style", "블리자드 이름표 스타일")
T("Blizzard raid target icon on enemy plates", "적 이름표의 블리자드 공격대 대상 아이콘")
T("Blizzard setting", "블리자드 설정")
T("Blizzard shield", "블리자드 방패")
T("Blizzard spell icon", "블리자드 주문 아이콘")
T("Blizzard supplies the castbar texture, colors, progress and interrupts. Customize its text and details here. Select and move each cast element in the preview; positions apply outside combat.", "시전 바 텍스처, 색상, 진행 상태, 차단은 블리자드가 제공합니다. 여기서 텍스트와 세부 정보를 사용자 지정하세요. 미리보기에서 각 시전 요소를 선택해 옮길 수 있으며, 위치는 전투 중이 아닐 때 적용됩니다.")
T("Blizzard supplies the icons. The Suite keeps its own button plates, bar frame and spacing. Native clicks, tooltips and notifications stay intact.", "아이콘은 블리자드가 제공합니다. Suite는 자체 버튼 배경판, 바 프레임, 간격을 유지합니다. 기본 클릭, 툴팁, 알림은 그대로 작동합니다.")
T("Blizzard supplies the name and health values. Mapko requests full enemy plates and both health values so normal enemies show text too. Width and height change only the enemy health bar in pixels; 0 keeps the selected bar dimensions. Backdrop, border and role fill are separate live skin layers in the preview; right-click a layer for its setting. Role colors use the saved palette; mana is only a caster hint. Open the three-dot menu here or Nameplates in MSUF Colors to change the palette.", "이름과 생명력 값은 블리자드가 제공합니다. Mapko는 일반 적에게도 글자가 표시되도록 전체 적 이름표와 두 생명력 값을 요청합니다. 너비와 높이는 적 생명력 막대만 픽셀 단위로 변경하며, 0은 선택한 크기를 유지합니다. 배경, 테두리, 역할 채우기는 미리보기의 별도 외형 계층입니다. 계층을 우클릭하면 해당 설정을 엽니다. 역할 색상은 저장된 팔레트를 사용하며, 마나는 주문 시전자 여부를 추정하는 단서입니다. 팔레트는 여기의 점 세 개 메뉴 또는 MSUF 색상의 이름표에서 변경하세요.")
T("Blizzard symbols", "블리자드 기호")
T("Blizzard window controls", "블리자드 창 컨트롤")
