T("Blizzard's Cooldown Manager stops completely. While your MSUF frames follow its bars, MSUF keeps it running invisibly.", "블리자드 재사용 대기시간 관리자가 완전히 멈춥니다. MSUF 프레임이 그 바를 따르는 동안에는 MSUF가 관리자를 보이지 않게 계속 실행합니다.")
T("Blizzard's bars keep running, invisible, so frames that other addons attach to them stay in place.", "블리자드 바는 보이지 않은 채 계속 실행되므로, 다른 애드온이 거기에 붙인 프레임은 제자리를 유지합니다.")
