T("Blizzard's original Micro Bar and buttons. Use Blizzard Edit Mode to move it.", "블리자드 원래의 마이크로 메뉴와 버튼입니다. 이동하려면 블리자드 편집 모드를 사용하세요.")
T("Blizzard's own buttons stay functional. The row is their starting position; drag each icon freely in the preview.", "블리자드 자체 버튼은 그대로 작동합니다. 이 줄은 시작 위치일 뿐이며, 미리보기에서 각 아이콘을 자유롭게 끌 수 있습니다.")
T("Blizzard's own cooldown swipe fills the ring: the global cooldown after each ability, and casts or channels while they run. A cast takes the place of the global cooldown until it ends; the bright edge marks how far the cast has come.", "블리자드의 재사용 대기시간 애니메이션이 고리를 채웁니다: 각 기술 후의 전역 재사용 대기시간, 그리고 진행 중인 시전이나 정신 집중. 시전이 끝날 때까지는 시전이 전역 재사용 대기시간을 대신하며, 밝은 가장자리가 시전 진행 정도를 보여 줍니다.")
