T("Bounded named-root traversal\nDedicated visual-only Edit Mode coverage\nExplicit secure controls remain untouched\nBlizzard frames keep their parents and scripts; only Suite-made selection indicators move\nNo polling or tickers; OnUpdate runs only while a window corner is dragged", "이름 있는 루트 창만 제한적으로 순회\n편집 모드에는 시각 효과만 전용으로 적용\n명시적인 보안 컨트롤은 그대로 유지\n블리자드 프레임은 부모와 스크립트를 유지하며 Suite가 만든 선택 표시기만 이동\n폴링이나 티커 없음. OnUpdate는 창 모서리를 끄는 동안에만 실행")
