T("Bubbles outside instances can take the MSUF look; Blizzard locks the ones inside instances. Each source keeps Blizzard's look or uses the MSUF one: the shared look or its own font, size, colors, spacing and width. A bubble is matched to the line it shows right after that line arrives. Turning bubbles off inside instances uses Blizzard's bubble settings and gives them back when you leave or turn it off.", "인스턴스 밖의 말풍선은 MSUF 모양을 쓸 수 있으며, 인스턴스 안의 말풍선은 블리자드가 잠급니다. 각 출처는 블리자드 모양을 유지하거나 MSUF 모양을 사용하며, 공통 모양 또는 자체 글꼴, 크기, 색상, 여백, 너비를 쓸 수 있습니다. 말풍선은 대사가 도착한 직후 그 말풍선이 보여 주는 줄과 짝지어집니다. 인스턴스 안에서 말풍선을 끄는 기능은 블리자드 말풍선 설정을 사용하며, 인스턴스를 나가거나 이 기능을 끄면 원래대로 돌려놓습니다.")
