T("Choose %s for \"%s\".", "%s 항목을 선택하세요. 설정: \"%s\".")
T("Choose Clean Modern, Midnight Blue, MSUF Forever Glass, Midnight Dark or Class Style for Skinning and enabled Suite modules. Modules enabled later inherit it.", "스킨 적용과 활성화된 Suite 모듈에 깔끔한 모던, Midnight Blue, MSUF Forever 유리, Midnight Dark 또는 직업 스타일을 선택하세요. 나중에 활성화한 모듈도 이를 따릅니다.")
T("Choose Clean Modern, Midnight Blue, Midnight Dark, MSUF Forever or Class Style. This changes only the bag window colors and opacity; item slots and Blizzard bag actions remain intact.", "깔끔한 모던, Midnight Blue, Midnight Dark, MSUF Forever 또는 직업 스타일을 선택하세요. 가방 창의 색상과 불투명도만 바뀌며, 아이템 칸과 블리자드 가방 동작은 유지됩니다.")
T("Choose Clean Modern, Midnight Blue, neutral Midnight Dark glass or MSUF Forever's dark gold frame. All use MSUF's bar texture and font. Turn the 20 XP divisions on or off. The lower line can show session gain, XP per hour and time to level. Move or resize the bar in MSUF Edit Mode; its popup edits X, Y, width, height and scale. Hover for exact values. A session survives /reload and starts fresh on the next login.", "Clean Modern, Midnight Blue, 중성적인 Midnight Dark 유리 또는 MSUF Forever의 어두운 금색 테두리를 선택하세요. 모든 스타일은 MSUF의 바 텍스처와 글꼴을 사용합니다. 경험치 바의 20칸 구분선을 켜거나 끌 수 있습니다. 아래 줄에는 이번 접속에서 얻은 경험치, 시간당 경험치와 다음 레벨까지 예상 시간을 표시할 수 있습니다. MSUF 편집 모드에서 바를 이동하거나 크기를 조절하고 팝업에서 X, Y, 너비, 높이와 배율을 설정합니다. 마우스를 올리면 정확한 수치를 볼 수 있습니다. 세션은 /reload 뒤에도 유지되며 다음 로그인 때 새로 시작합니다.")
T("Choose Custom layout to set the order of total, per-second and percent values, then pick spaces, brackets or a separator. The percent switch controls main rows; breakdown rows show available shares. Unavailable shares are omitted. Primary means per second for DPS/HPS and total for other meters. Text settings also apply to headers, details and the floating timer. Slug uses WoW's crisp font renderer with an outline and no shadow. Protected values show without a percentage until combat ends.", "사용자 지정 배치를 선택하면 총량, 초당, 백분율 값의 순서를 정하고 공백, 괄호 또는 구분자를 고를 수 있습니다. 백분율 스위치는 기본 행을 제어하며, 세부 내역 행에는 사용 가능한 비율이 표시됩니다. 사용할 수 없는 비율은 생략됩니다. '주 값'은 DPS/HPS에서는 초당 값, 다른 측정기에서는 총량을 뜻합니다. 텍스트 설정은 머리글, 세부 정보, 떠 있는 타이머에도 적용됩니다. Slug는 WoW의 선명한 글꼴 렌더러를 사용하며 외곽선은 있고 그림자는 없습니다. 보호된 값은 전투가 끝날 때까지 백분율 없이 표시됩니다.")
T("Choose Suite modules", "Suite 모듈 선택")
T("Choose a Suite layout", "Suite 배치 선택")
T("Choose a data source", "정보 항목 선택")
T("Choose a font", "글꼴 선택")
T("Choose a line, then press Ctrl+C", "줄을 선택한 후 Ctrl+C를 누르세요")
T("Choose a look", "외형 선택")
T("Choose a look and when the Suite bar appears. Visibility rules use the Suite layout; Blizzard layout keeps Blizzard's visibility. MSUF Edit Mode reveals the bar for moving.", "외형과 Suite 바가 표시될 시점을 선택하세요. 표시 규칙은 Suite 배치에서 사용되며, 블리자드 배치는 블리자드의 표시 설정을 따릅니다. MSUF 편집 모드에서는 이동할 수 있도록 바가 표시됩니다.")
T("Choose a look below; this sample follows your changes.", "아래에서 외형을 선택하세요. 이 예시는 변경 사항을 따라 바뀝니다.")
T("Choose a look, then adjust its colors.", "스타일을 고른 뒤 색상을 조정하세요.")
T("Choose a preset below or fine-tune with the slider.", "아래에서 프리셋을 선택하거나 슬라이더로 세밀하게 조정하세요.")
T("Choose a profile that exists in both parts of the suite", "Suite의 두 부분 모두에 있는 프로필을 선택하세요")
T("Choose a random owned Hearthstone variant for the next click", "다음 클릭에 보유한 귀환석 변형 무작위 선택")
T("Choose a smaller stack size and make sure the item is unlocked, your cursor is empty and you are out of combat.", "더 작은 묶음 크기를 선택하고 아이템이 잠기지 않았으며, 커서가 비어 있고 전투 중이 아닌지 확인하세요.")
T("Choose a sound", "소리 선택")
T("Choose a starting point. Existing bars stay unchanged.", "시작할 구성을 선택하세요. 기존 바는 변경되지 않습니다.")
T("Choose a style above or change these colors to make a Custom look. Rows update immediately.", "위에서 스타일을 선택하거나 색상을 변경하여 사용자 정의 모양을 만드세요. 행이 즉시 업데이트됩니다.")
T("Choose a style, font and coverage in minutes. Every deeper control remains available in Expert mode.", "몇 분 만에 스타일, 글꼴, 적용 범위를 고르세요. 더 세부적인 설정은 모두 전문가 모드에서 사용할 수 있습니다.")
T("Choose a template", "템플릿을 선택하세요")
T("Choose an MSUF font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Label, value and warning colors are separate.", "MSUF 글꼴, 외곽선, 그림자와 부드럽게, 선명하게, Slug 중 렌더링 방식을 선택하세요. Slug에는 그림자가 없습니다. 라벨, 값, 경고 색상은 따로 설정합니다.")
T("Choose an MSUF or SharedMedia font and bar texture. Font size, outline, shadow, Smooth/Sharp/Slug rendering, bar height and spacing update the HUD immediately. Slug has no shadow.", "MSUF 또는 SharedMedia 글꼴과 바 텍스처를 선택하세요. 글꼴 크기, 외곽선, 그림자, 부드럽게/선명하게/Slug 렌더링, 바 높이, 간격이 HUD에 즉시 반영됩니다. Slug에는 그림자가 없습니다.")
T("Choose broad UI families. Dedicated secure behavior and semantic artwork remain untouched.", "넓은 UI 분류를 선택하세요. 전용 보안 동작과 의미가 있는 아트워크는 그대로 유지됩니다.")
T("Choose broker names and discovered currency IDs per place. Select your current-season crest currencies from the native currency list; saved currency selections work after login without visiting an upgrade NPC. Selection order and separator control the crest block. Observed upgrade stages remain available as an alternative after selecting an upgrade item this login. Hearthstone actions require a deliberate click.", "각 칸의 브로커 이름과 발견한 화폐 ID를 선택하세요. 기본 화폐 목록에서 현재 시즌의 문장 화폐를 선택하세요. 저장된 화폐 선택은 강화 NPC를 방문하지 않아도 로그인 후 작동합니다. 선택 순서와 구분자는 문장 블록을 제어합니다. 이번 로그인 중 강화할 아이템을 선택한 후에는 확인된 강화 단계를 대안으로 사용할 수 있습니다. 귀환석 동작은 의도적으로 클릭해야 실행됩니다.")
T("Choose buffs and consumables to track.", "추적할 강화 효과와 소모품을 선택하세요.")
T("Choose clean window controls and a complete Micro Bar style, then tune individual artwork only when needed.", "깔끔한 창 버튼과 완성된 마이크로 메뉴 스타일을 고른 뒤, 필요할 때만 개별 아트워크를 조정하세요.")
T("Choose coverage", "적용 범위 선택")
T("Choose crest currencies", "문장 화폐 선택")
T("Choose currencies", "화폐 선택")
T("Choose data", "정보 선택")
T("Choose data for place %d", "자리 %d의 데이터 선택")
T("Choose data source", "정보 항목 선택")
T("Choose discovered currency", "발견한 화폐 선택")
T("Choose each Blizzard popup separately. The feature hides its window when it appears and leaves the underlying game events intact. Combat lockdown can prevent hiding a protected window.", "각 블리자드 팝업을 개별적으로 선택하세요. 이 기능은 나타날 때 창을 숨기고 기본 게임 이벤트를 그대로 유지합니다. 전투 잠금은 보호된 창을 숨기는 것을 방지할 수 있습니다.")
T("Choose individual recurring UI errors to hide with Blizzard's own message filter.", "Blizzard의 자체 메시지 필터로 숨길 개별 반복 UI 오류를 선택하세요.")
T("Choose loaded broker", "불러온 브로커 선택")
T("Choose observed seasonal stages", "확인된 시즌 단계 선택")
T("Choose one font for Blizzard UI text. Existing sizes, outlines, shadows and accessibility scaling are preserved.", "블리자드 UI 텍스트에 사용할 글꼴 하나를 고르세요. 기존 크기, 외곽선, 그림자, 접근성 배율은 유지됩니다.")
T("Choose the detailed character view and its extra information. Changing the view reloads the UI.", "상세 캐릭터 보기와 추가 정보를 선택하세요. 보기를 바꾸면 UI를 다시 불러옵니다.")
T("Choose the dungeon difficulties where MSUF starts the combat log. Mythic+ begins when the keystone starts.", "MSUF가 전투 기록을 시작할 던전 난이도를 선택하세요. 신화+는 쐐기돌이 시작될 때 기록을 시작합니다.")
T("Choose the map shape, then adjust its border and outer shadow.", "지도 모양을 선택한 다음 테두리와 바깥 그림자를 조정하세요.")
T("Choose the raid difficulties where MSUF starts the combat log.", "MSUF가 전투 기록을 시작할 공격대 난이도를 선택하세요.")
T("Choose the shared button colors and frame. Layout, bindings and visibility stay as set. Changing an individual color switches the label to Custom.", "공용 버튼 색상과 프레임을 선택하세요. 배치, 단축키, 표시 여부는 설정한 대로 유지됩니다. 개별 색상을 바꾸면 라벨이 '사용자 지정'으로 바뀝니다.")
T("Choose the values shown on each bar.", "각 막대에 표시할 값을 선택하세요.")
T("Choose what the Suite tracker lists and when it steps aside.", "Suite 추적기가 표시할 내용과 물러날 때를 선택합니다.")
T("Choose where recent actions appear. Delves have their own switch; battlegrounds and arenas share one, and other scenarios follow Outside instances. Where the tracker is switched off, it does not listen to your casts.", "최근 행동을 표시할 곳을 고릅니다. 구렁은 별도 스위치가 있고, 전장과 투기장은 하나를 함께 쓰며, 그 밖의 시나리오는 '인스턴스 밖'을 따릅니다. 꺼진 곳에서는 시전을 감지하지 않습니다.")
T("Choose which Blizzard interfaces receive the skin. Blizzard keeps their interactions.", "스킨을 적용할 블리자드 인터페이스를 선택하세요. 상호작용은 블리자드가 그대로 처리합니다.")
T("Choosing a look updates Skinning and every enabled Suite module. Modules enabled later inherit it. New skin profiles start with %s.", "외형을 선택하면 스킨 적용 설정과 활성화된 모든 Suite 모듈이 갱신됩니다. 나중에 활성화하는 모듈도 이를 이어받습니다. 새 스킨 프로필은 %s(으)로 시작합니다.")
T("Cinematic confirmation can be skipped after you choose to exit. Automatic skipping is a separate option and also skips movies. Both stay inactive during combat, and a vehicle sequence always keeps its exit confirmation. Hide tutorials while this helper is enabled, prefill the DELETE word while keeping the final confirmation manual, hide only the successful screenshot notice, or open your character window at merchants on the tab you used last. At the auction house, Blizzard's filter button is marked while Current Expansion Only is off; tick it there once and Blizzard keeps it for this character.", "나가기를 선택한 뒤 시네마틱 확인을 건너뛸 수 있습니다. 자동 건너뛰기는 별도 옵션이며 동영상도 건너뜁니다. 두 기능은 전투 중 작동하지 않으며, 차량 탑승 장면은 항상 내리기 확인 창을 유지합니다. 이 도우미는 튜토리얼 숨기기, 최종 확인은 직접 하도록 삭제 확인 문구 미리 입력하기, 스크린샷 성공 알림만 숨기기, 상인에게서 마지막으로 사용한 탭으로 캐릭터 창 열기를 지원합니다. 경매장에서는 '현재 확장팩만'이 꺼져 있는 동안 블리자드의 필터 버튼이 표시됩니다. 그곳에서 한 번 선택하면 블리자드가 이 캐릭터에 대해 기억합니다.")
T("Cinematic zone and event announcements in the Suite look.", "Suite 외형으로 표시되는 영화 같은 지역 및 이벤트 공지입니다.")
