T("Clean Modern is the Retail default; MSUF Forever is the Forever default. Midnight Blue keeps the original blue glass. Open a section's three-dot menu to change its colors, or use MSUF Colors for the full palette. Your own color changes become Custom.", "깔끔한 모던은 본 서버 기본값이며 MSUF Forever는 Forever 기본값입니다. Midnight Blue는 기존 파란 유리 느낌을 유지합니다. 섹션의 점 세 개 메뉴에서 색상을 바꾸거나 MSUF 색상에서 전체 팔레트를 조정하세요. 색상을 직접 변경하면 사용자 지정으로 바뀝니다.")
T("Clean Modern uses matte panels with white accents. Midnight Blue keeps the original blue palette. Midnight Dark uses neutral charcoal glass; MSUF Forever retains its muted gold. Color changes become Custom.", "깔끔한 모던은 흰색 강조가 있는 무광 패널을 사용합니다. Midnight Blue는 기존 파란 팔레트를 유지합니다. Midnight Dark는 중성 짙은 회색 유리 느낌을, MSUF Forever는 차분한 금색을 유지합니다. 색상을 변경하면 사용자 지정으로 바뀝니다.")
T("Clean Modern, Midnight Blue, Midnight Dark and MSUF Forever are complete looks in Style. Color palettes here change colors only; use Expert mode for every UI state.", "깔끔한 모던, Midnight Blue, Midnight Dark, MSUF Forever는 스타일에 있는 완성된 외형입니다. 여기의 색상 팔레트는 색상만 바꿉니다. 모든 UI 상태를 조정하려면 전문가 모드를 사용하세요.")
