T("Clear only new mount, pet and toy fanfares acquired while this helper is active. Your collection entries remain available. Each collection type can be switched off independently.", "이 기능이 켜진 동안 새로 얻은 탈것, 애완동물과 장난감의 '신규' 알림만 지웁니다. 수집품 항목은 그대로 남습니다. 각 수집품 유형을 따로 끌 수 있습니다.")
