T("Click a reminder to cast its spell or use its item. Aura checks run on relevant events; there is no repeating scan.", "알림을 클릭하면 해당 주문을 시전하거나 아이템을 사용합니다. 오라 확인은 관련 이벤트가 발생할 때만 실행되며, 반복 검사는 하지 않습니다.")
