T("Click opens the world map", "클릭 시 세계 지도 열기")
T("Click the minimap button for Blizzard's specialization and loot specialization choices. Choices are disabled in combat and the button hides when both menus are turned off.", "블리자드의 전문화 및 전리품 전문화 선택을 보려면 미니맵 버튼을 클릭하세요. 전투 중에는 선택이 비활성화되고 두 메뉴가 모두 꺼지면 버튼이 숨겨집니다.")
T("Click the preview to open the matching settings.", "미리보기를 클릭하면 해당 설정이 열립니다.")
T("Click to edit this bar, right-click for its actions. Drop a spell here to move it to this bar.", "클릭하면 이 바를 편집하고, 오른쪽 클릭하면 동작 메뉴가 열립니다. 주문을 여기에 놓으면 이 바로 옮겨집니다.")
T("Click to open its Basics: size and attachment.", "클릭하면 기본 설정(크기 및 붙이기)이 열립니다.")
T("Click to open the death recap.", "클릭하여 사망 요약 열기.")
