T("Click to select; drag or use arrow keys; edit exact X/Y below.", "클릭해 선택하고, 끌거나 화살표 키로 옮기세요. 정확한 X/Y는 아래에서 편집합니다.")
T("Click to show or hide the collected buttons.", "클릭하여 모은 버튼을 표시하거나 숨깁니다.")
