T("Double-click a search result to open Blizzard's application dialog. With submit on double-click, the second click also signs up with the roles already chosen in that dialog; hold Shift to review it instead. A saved note can appear beside the dialog for copying; it is stored when you finish editing.", "검색 결과를 두 번 클릭하면 블리자드 신청 창이 열립니다. 두 번 클릭으로 신청을 켜면 두 번째 클릭이 그 창에서 이미 고른 역할로 바로 신청하며, Shift를 누르고 있으면 대신 창을 확인할 수 있습니다. 저장한 메모를 복사용으로 창 옆에 표시할 수 있으며, 편집을 마치면 저장됩니다.")
T("Double-click a search result to open Blizzard's normal application dialog.", "검색 결과를 두 번 클릭하면 Blizzard의 일반 응용 프로그램 대화 상자가 열립니다.")
T("Drag a window by its top edge; drag the bottom-right corner to scale it. The top-right minus button collapses compatible windows to a restore tab. Bags and protected windows keep their native behavior.", "창의 위쪽 가장자리를 끌어 옮기고, 오른쪽 아래 모서리를 끌어 크기를 조절하세요. 오른쪽 위의 빼기 버튼을 누르면 호환되는 창이 복원 탭으로 접힙니다. 가방과 보호된 창은 기본 동작을 유지합니다.")
T("Drag announcements in MSUF Edit Mode, or set their timing, scale and exact position here.", "MSUF 편집 모드에서 공지를 끌어 옮기거나, 여기에서 표시 시간, 배율, 정확한 위치를 설정하세요.")
T("Drag or use arrows to move; Shift: 5, Ctrl: 10.", "끌거나 화살표 키로 이동하세요. Shift: 5, Ctrl: 10.")
T("Drag or use arrows to move; click for settings.", "끌거나 화살표 키로 이동하고, 클릭하면 설정이 열립니다.")
T("Drag the bag title to move it; click for options.", "가방 제목을 드래그해 이동하고 클릭해 설정하세요.")
T("Drag the bar's edge to move it on screen.", "바의 가장자리를 끌어 화면에서 옮기세요.")
T("Drag the reagent bag title while it is open to move it independently. Click the title for bag options. Reset its position in MSUF Edit Mode to follow Blizzard's normal bag layout again.", "재료 가방이 열려 있을 때 제목을 끌면 따로 옮길 수 있습니다. 제목을 클릭하면 가방 옵션이 열립니다. MSUF 편집 모드에서 위치를 초기화하면 다시 블리자드의 기본 가방 배치를 따릅니다.")
T("Drag the result card in MSUF Edit Mode, or set its screen anchor, width, scale and position here.", "MSUF 편집 모드에서 결과 카드를 끌어 이동하거나 여기서 화면 기준점, 너비, 크기, 위치를 설정합니다.")
T("Drag the title of an open bag to move it. Click the title for bag options. Each bag keeps its own position. Blizzard shows your current gold on the right; the optional Session value on the left shows the change since login and survives /reload. Adjust the combined bag size here or in its MSUF Edit Mode popup. Reset position in Edit Mode returns the window to Blizzard's normal anchor.", "열린 가방의 제목을 끌어 옮기세요. 제목을 클릭하면 가방 옵션이 열립니다. 가방마다 위치가 따로 저장됩니다. 오른쪽에는 블리자드가 현재 골드를 표시하며, 왼쪽의 선택적 세션 값은 접속 이후의 변화량을 보여 주고 /reload 후에도 유지됩니다. 통합 가방 크기는 여기나 MSUF 편집 모드 팝업에서 조정하세요. 편집 모드에서 위치를 초기화하면 창이 블리자드 기본 위치로 돌아갑니다.")
