T("Drop an item here to add it without moving it.", "아이템을 여기에 놓으면 실제로 이동하지 않고 추가합니다.")
T("Drop an item onto Pinned items in the category sidebar to keep it at the top of every view. Recent items lists up to 200 item types this character received, also across logins; each leaves the list once it is older than the hours set here, and Clear recent items empties it sooner. Neither action moves or deletes an item.", "사이드바의 고정 아이템에 아이템을 놓으면 모든 보기의 맨 위에 표시됩니다. 최근 아이템은 이 캐릭터가 받은 아이템을 접속이 바뀌어도 최대 200종까지 보여 줍니다. 각 아이템은 여기서 정한 시간보다 오래되면 목록에서 빠지며, 최근 아이템 지우기로 더 일찍 비울 수 있습니다. 두 작업 모두 아이템을 이동하거나 삭제하지 않습니다.")
