T("Enchant: check = present, ! = missing or low quality, - = not needed, ? = unverified. Upgrade: + = levels remain, check / MAX = track complete. The bar shows the current track level, not upgrades previously purchased.", "마법부여: 체크 = 있음, ! = 없음 또는 낮은 품질, - = 불필요, ? = 미확인. 강화: + = 남은 단계 있음, 체크 / 최대 = 강화 단계 완료. 막대는 이전에 구매한 강화가 아니라 현재 강화 단계를 표시합니다.")
