T("Enter a spell name or ID on MSUF action bars. Its buttons glow from this buff on you. A page change in combat pauses the glow until combat ends.", "MSUF 행동 단축바에 있는 주문 이름이나 ID를 입력하세요. 자신에게 이 강화 효과가 있으면 해당 버튼이 반짝입니다. 전투 중 페이지가 바뀌면 전투가 끝날 때까지 반짝임이 일시 중지됩니다.")
T("Enter a talent or spell name or ID, then press Enter. Every required spell must be learned. Empty removes this condition.", "특성 또는 주문 이름이나 ID를 입력한 뒤 Enter를 누르세요. 필수 주문을 모두 배워야 합니다. 비워 두면 이 조건을 제거합니다.")
T("Enter a talent or spell name or ID, then press Enter. The entry is hidden while any excluded spell is learned. Conditions update outside combat.", "특성 또는 주문 이름이나 ID를 입력한 뒤 Enter를 누르세요. 제외한 주문 중 하나라도 배웠으면 항목을 숨깁니다. 조건은 전투 중이 아닐 때 갱신됩니다.")
