T("Enter a valid spell name or ID", "유효한 주문 이름이나 ID를 입력하세요.")
T("Enter a valid talent or spell name or ID.", "올바른 특성 또는 주문 이름이나 ID를 입력하세요.")
T("Enter up to 200 item IDs. A button appears only at a merchant and previews eligible stacks; clicking it opens a confirmation. The helper checks item identity, quality, value, quest status and bag position again before requesting sales. Equippable items require a separate opt-in.", "아이템 ID를 최대 200개 입력하세요. 버튼은 상인에게서만 나타나며 판매 가능한 묶음을 미리 보여줍니다. 클릭하면 확인창이 열립니다. 판매를 요청하기 전에 아이템 ID, 품질, 가격, 퀘스트 여부와 가방 위치를 다시 검사합니다. 착용 가능한 아이템은 별도로 허용해야 합니다.")
T("Enter up to eight spell IDs for movement abilities. When movement begins, the first known, ready and usable spell appears briefly; a shared 20-second cooldown limits notices. Empty IDs do no work. MSUF Edit Mode moves the cue.", "이동 기술의 주문 ID를 최대 8개 입력하세요. 이동을 시작하면 배웠고 사용할 수 있는 첫 번째 기술이 잠깐 표시됩니다. 모든 알림에 공통으로 적용되는 20초 재사용 대기시간이 반복 알림을 제한합니다. ID가 비어 있으면 아무 작업도 하지 않습니다. MSUF 편집 모드에서 알림을 이동할 수 있습니다.")
T("Equal", "균등")
T("Equipment", "장비")
T("Equipment category", "장비 분류")
T("Equipment choices", "장비 선택")
T("Equipment choices (the list that opens from a gear slot) show the item level on each item, so you can compare without hovering. The arrows beside the gear slots can be hidden; hold Alt over a slot to open its choices.", "장비 선택(장비 슬롯에서 열리는 목록)에 각 아이템의 레벨이 표시되어 마우스를 올리지 않고도 비교할 수 있습니다. 장비 슬롯 옆 화살표는 숨길 수 있으며, 슬롯 위에서 Alt를 누르면 선택 목록이 열립니다.")
T("Equipment item levels appear in the upper right of each slot. Choose a font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Missing item data appears when the client provides it.", "장비 아이템 레벨은 각 칸의 오른쪽 위에 표시됩니다. 글꼴, 외곽선, 그림자와 부드럽게, 선명하게, Slug 중 렌더링 방식을 선택하세요. Slug에는 그림자가 없습니다. 누락된 아이템 데이터는 클라이언트가 제공하면 표시됩니다.")
