T("Every color, look, geometry, font, icon, Micro Bar, Blizzard skin and HUD setting travels with the profile.", "모든 색상, 외형, 기하학, 글꼴, 아이콘, 마이크로 메뉴, 블리자드 스킨, HUD 설정이 프로필과 함께 옮겨집니다.")
T("Every specialization already has it.", "모든 전문화에 이미 있습니다.")
T("Every spell of this bar, unlearned ones included. On a buff bar, Add spells offers received buffs such as Power Infusion and Innervate; Buff on me also accepts a buff aura ID or resolvable name and tracks that ID from any caster. With Show missing buffs off, only active buffs appear. The preview edits entries too: click for options, drag to reorder or onto a bar above, middle-click to remove (with undo). Removed spells stay under Add spells. Lists are kept per specialization.", "배우지 않은 주문을 포함한 이 바의 모든 주문입니다. 강화 효과 바에서는 '주문 추가'로 마력 주입이나 정신 자극처럼 받는 강화 효과를 추가할 수 있으며, '나에게 걸린 강화 효과'는 강화 효과 오라 ID나 확인 가능한 이름도 받아 어느 시전자의 것이든 그 ID를 추적합니다. '빠진 강화 효과를 흐리게 표시'를 끄면 활성 강화 효과만 표시됩니다. 미리보기에서도 항목을 편집할 수 있습니다: 클릭하면 옵션, 끌면 순서 변경 또는 위의 바로 이동, 가운데 클릭하면 제거(실행 취소 가능). 제거한 주문은 '주문 추가' 아래에 남습니다. 목록은 전문화별로 저장됩니다.")
