T("For Warlocks: show Burning Rush only while its aura is active in combat. Blizzard's native aura container follows the aura; Suite does not scan auras. MSUF Edit Mode shows a sample and moves the cue.", "흑마법사는 전투 중 불타는 돌진 강화 효과가 활성화된 동안에만 알림을 표시합니다. 블리자드 기본 오라 컨테이너가 이를 추적하며 Suite는 오라를 스캔하지 않습니다. MSUF 편집 모드에서 예시를 보고 알림을 이동할 수 있습니다.")
