T("Forever only. Route times are learned from completed flight-master journeys and kept in this profile. A first journey has no invented estimate. Early landing does not overwrite a full-route time. Intermediate stops come from the native taxi map; its tooltip can preview the route. Land at next stop requests the next available landing point.", "Forever 전용입니다. 완료한 비행 조련사 이동 시간을 학습하여 이 프로필에 저장합니다. 첫 이동에는 임의 예상 시간을 표시하지 않습니다. 조기 착륙은 전체 경로 시간을 덮어쓰지 않습니다. 중간 정류장은 기본 비행 지도로 확인하고 툴팁에서 경로를 미리 볼 수 있습니다. ‘다음 정류장에서 착륙’은 다음 가능한 착륙 지점을 요청합니다.")
