T("Friendly player display chooses Blizzard's setting, names for all friendly players, names for party / raid only, or health bars. Names only hides Blizzard bars, casts and auras for friendly players; it does not change NPC or enemy plates. Group / outsider in the preview only changes the sample. Blizzard can forbid changes to friendly plates in instances; those frames stay under Blizzard's control.", "우호적 플레이어 표시에서는 블리자드 설정, 모든 우호적 플레이어의 이름, 파티 / 공격대원만 이름, 또는 생명력 바 중에서 선택합니다. '이름만'은 우호적 플레이어의 블리자드 바, 시전, 오라를 숨기며 NPC나 적 이름표는 바꾸지 않습니다. 미리보기의 '그룹 / 외부인'은 예시만 바꿉니다. 인스턴스에서는 블리자드가 우호적 이름표 변경을 금지할 수 있으며, 그런 프레임은 계속 블리자드가 제어합니다.")
