T("Hide Blizzard's main tooltip in combat, in instances, or for selected item, spell and unit tooltips. MSUF unit and group frame tooltips keep their own visibility settings; aura tooltips keep their Show Tooltip switches. Each choice works independently. A hidden tooltip turns fully transparent, so Blizzard keeps handling it as usual.", "전투 중이나 인스턴스 안에서 또는 선택한 아이템, 주문, 유닛 툴팁에 대해 블리자드의 기본 툴팁을 숨깁니다. MSUF 유닛 및 그룹 프레임 툴팁은 자체 표시 설정을 따르며, 오라 툴팁은 각각의 툴팁 표시 옵션을 따릅니다. 각 항목은 독립적으로 작동합니다. 숨긴 툴팁은 완전히 투명해지므로 블리자드가 평소처럼 계속 관리합니다.")
