T("Hold Alt to see the ID of an item, spell, creature, quest, currency or temporary weapon enchant on its tooltip, or press Alt while the tooltip is open; the IDs stay until the tooltip is built again. Spell icon IDs and Blizzard's account character currency data are optional, and that data joins an open tooltip when it arrives. No ID or quantity appears when the client keeps it private.", "Alt를 누른 채로 아이템, 주문, 생물, 퀘스트, 화폐 또는 임시 무기 마법부여의 ID를 툴팁에서 보거나, 툴팁이 열린 상태에서 Alt를 누르세요. ID는 툴팁이 다시 만들어질 때까지 남습니다. 주문 아이콘 ID와 블리자드의 다른 캐릭터 화폐 데이터는 선택 사항이며, 그 데이터는 도착하면 열린 툴팁에 추가됩니다. 클라이언트가 비공개로 두는 ID나 수량은 표시되지 않습니다.")
T("Hold Alt to show item, spell, creature, quest, currency and temporary weapon enchant IDs on the main tooltip.", "물품, 주문, 생물, 퀘스트, 화폐, 임시 무기 마법부여에 마우스를 올리고 Alt를 누르면 기본 툴팁에 ID가 표시됩니다.")
T("Hold Midnight Artisan payouts while Shard of Dundun is capped", "둔둔의 조각 한도에 도달하면 한밤 장인 보상 보관")
T("Hold Shift to pause. Quests with a money cost and quests with a reward choice always stay manual.", "Shift 키를 누르고 있으면 일시 중지됩니다. 골드가 드는 퀘스트와 보상을 골라야 하는 퀘스트는 항상 수동으로 처리합니다.")
T("Hold the selected key while clicking Release Spirit. The release button stays hidden until you hold it; resurrection and death recap remain available. Choose where to use the protection. Blizzard's automatic release timer is unchanged.", "선택한 키를 누른 상태로 영혼 해제를 클릭합니다. 키를 누를 때까지 해제 버튼이 숨겨지며 부활과 사망 분석은 계속 사용할 수 있습니다. 보호를 적용할 장소를 선택합니다. 블리자드의 자동 영혼 해제 타이머는 바뀌지 않습니다.")
T("Hold to release", "길게 눌러 영혼 해제")
