T("Hover a spell and type /msufcopyspell to select its public ID in a small edit box. Press Ctrl+C to copy it. You can also pass an ID to the command. No clipboard action runs automatically.", "주문을 마우스로 가리키고 /msufcopyspell을 입력하여 작은 편집 상자에서 공개 ID를 선택하세요. Ctrl+C를 눌러 복사하세요. 명령에 ID를 전달할 수도 있습니다. 클립보드 작업이 자동으로 실행되지 않습니다.")
