T("How the icons line up and grow. A free bar's position counts from the screen center; an attached bar's is an offset from its attach point. Excess cooldowns can move past Maximum icons to another enabled cooldown bar. The destination must have overflow off; chained routes are ignored.", "아이콘 정렬과 확장 방향입니다. 자유 배치 바는 화면 중앙을 기준으로, 연결된 바는 연결 지점을 기준으로 위치를 정합니다. 최대 아이콘 수를 넘는 재사용 대기시간은 다른 활성 바에 보낼 수 있습니다. 대상 바의 초과 아이콘 보내기는 꺼져 있어야 하며, 연속 전달은 무시됩니다.")
