T("Inside a raid the tracker turns into an encounter view at its usual place: boss name, pull timer, the bosses engaged right now with their health, your best wipe and your fastest kill. Phases come from DBM or BigWigs when one is installed; otherwise the phase stays open. A wipe with more bosses down beats one with fewer, and with the same count the one with less boss health left wins. Each character keeps its own records. Boss health shows only while the client reveals it.", "공격대 안에서는 추적기가 원래 위치에서 전투 보기로 바뀝니다. 우두머리 이름, 전투 타이머, 지금 전투 중인 우두머리와 생명력, 최고 전멸 기록과 최단 처치 시간을 표시합니다. 단계는 DBM이나 BigWigs가 설치되어 있으면 그 애드온에서 가져오며, 없으면 단계는 비워 둡니다. 처치한 우두머리가 더 많은 전멸이 더 좋은 기록이며, 수가 같으면 남은 우두머리 생명력이 적은 쪽이 앞섭니다. 기록은 캐릭터마다 따로 보관됩니다. 우두머리 생명력은 클라이언트가 공개할 때만 표시됩니다.")
