T("Keep Blizzard grid, or choose one Suite grid, physical bag groups or categories. Use Edit categories in the bag window to create, rename, reorder or disable your categories; drop items onto a sidebar category to assign them. Scroll or use Previous and Next for larger inventories; in combat every slot is shown at once. Combined stack counts are visual only; physical stacks are always restored at the bank, guild bank, mail, trade, auction house and merchant.", "블리자드 격자를 유지하거나 Suite 격자, 실제 가방별 묶음 또는 분류를 선택합니다. 가방 창의 분류 편집에서 분류를 만들거나 이름 변경, 순서 변경, 비활성화할 수 있습니다. 아이템을 사이드바 분류에 놓으면 지정됩니다. 아이템이 많으면 스크롤하거나 이전 및 다음을 사용하세요. 전투 중에는 모든 칸이 한 번에 표시됩니다. 묶음 개수 합산은 표시만 바꿉니다. 은행, 길드 은행, 우편, 거래, 경매장, 상인에서는 항상 실제 묶음으로 표시됩니다.")
