T("Learned dungeon portals use secure buttons. Group suggestions require a verified dungeon map or an exact destination match. Unknown destinations show no suggestion; buttons hide in combat.", "습득한 던전 순간이동 주문은 보안 버튼으로 사용합니다. 파티 추천에는 확인된 던전 지도 또는 정확히 일치하는 목적지가 필요합니다. 알 수 없는 목적지는 추천하지 않으며, 버튼은 전투 중 숨겨집니다.")
