T("Lightweight meter windows for damage, healing, interrupts, dispels, deaths and damage taken. They read the client's own combat data; Blizzard's meter window stays hidden while this module is active.", "피해, 치유, 차단, 해제, 죽음, 받은 피해를 보여 주는 가벼운 측정기 창입니다. 클라이언트 자체 전투 데이터를 읽으며, 이 모듈이 활성화된 동안 블리자드 측정기 창은 숨겨집니다.")
T("Lilac", "라일락")
T("Limit the whole highlight to combat, to instances or to the open world, then give the pointer ring, the global cooldown and the cast fill their own combat rule. Nothing follows the pointer while it is hidden.", "강조 표시 전체를 전투, 인스턴스 또는 필드로 제한한 다음, 포인터 고리, 전역 재사용 대기시간, 시전 채움에 각각의 전투 규칙을 정할 수 있습니다. 숨겨져 있는 동안에는 아무것도 포인터를 따라가지 않습니다.")
