T("List group pets", "그룹 소환수 표시")
T("Lists carried gem types beside Blizzard's socket window. Inspect each gem with its normal bag tooltip and confirm compatibility in the native socket window before applying it.", "블리자드 보석 홈 창 옆에 가방에 있는 보석 종류를 표시합니다. 각 보석의 기본 가방 툴팁을 확인하고, 장착하기 전에 게임 기본 보석 홈 창에서 호환성을 확인하세요.")
T("Lists the casts of attackable enemy nameplates while you are in a five-player dungeon, oldest first; the game runs each bar and timer. The game keeps spell, target, marker and interrupt details hidden from addons, so casts are never sorted or filtered by them: fading or hiding uses the game's important-spell flag (a hidden cast keeps its place in the list), raid markers sit on the spell icon, and the ready mark, an edge stripe or the whole bar, shows on interruptible casts while your interrupt is off cooldown. Dimming checks four times a second whether your interrupt reaches each listed enemy; a cast it cannot check stays bright. The interrupt is found from your talents and pet unless you enter a spell ID. MSUF Edit Mode shows sample casts for placing the list.", "5인 던전에 있는 동안 공격 가능한 적 이름표의 시전을 오래된 것부터 표시합니다. 각 바와 타이머는 게임이 직접 진행합니다. 게임은 주문, 대상, 징표, 차단 가능 여부를 애드온에 숨기므로 시전을 이를 기준으로 정렬하거나 거르지 않습니다. 흐리게 또는 숨기기는 게임의 중요 주문 표시를 사용하며(숨긴 시전도 목록의 자리를 유지합니다), 공격대 징표는 주문 아이콘에 표시되고, 준비 표시(가장자리 띠 또는 바 전체)는 차단 기술이 재사용 대기 중이 아닐 때 차단 가능한 시전에 나타납니다. 어둡게 표시는 초당 네 번 차단 기술이 목록의 각 적에게 닿는지 확인하며, 확인할 수 없는 시전은 밝게 유지됩니다. 주문 ID를 입력하지 않으면 특성과 소환수로 차단 기술을 찾습니다. MSUF 편집 모드에서 예시 시전으로 목록을 배치할 수 있습니다.")
T("Lists the casts of enemy nameplates in five-player dungeons, oldest first, with timers the game runs.", "5인 던전에서 적 이름표의 시전을 오래된 것부터 표시하며, 타이머는 게임이 진행합니다.")
