T("MSUF frames are attached to Blizzard's cooldown bars, so they keep running invisibly.", "MSUF 프레임이 블리자드 재사용 대기시간 바에 붙어 있으므로, 블리자드 바는 보이지 않게 계속 실행됩니다.")
