T("MSUF stops only a log it started. A log that was already on stays on. Re-entering selected content cancels a pending stop. WoW writes the log in its Logs folder.", "MSUF는 자신이 시작한 기록만 중지합니다. 이미 켜져 있던 기록은 계속 유지됩니다. 선택한 콘텐츠에 다시 들어가면 대기 중인 중지가 취소됩니다. WoW는 Logs 폴더에 기록을 저장합니다.")
