T("Mainline covers Rogue poisons, this season's flasks, augment runes and weapon oils, and the Well Fed food buff. Each category clicks the first matching item in your bags; an item you enter for it is tried first. Food is found in your bags by the game's eating spells: the food you enter comes first, then the newest one. With the gray reminder on, a category with nothing left stays visible without a click action. Assassination prefers Deadly Poison; Outlaw and Subtlety prefer Instant Poison. Dragon-Tempered Blades allows two poisons per category. Oils target equipped weapons; known Shaman or Paladin imbues suppress automatic oils.", "Mainline은 도적 독, 이번 시즌의 영약·증강의 룬·무기 기름, 음식 강화 효과인 포만감을 다룹니다. 각 분류는 클릭하면 가방에 있는 첫 번째 해당 아이템을 사용하며, 직접 입력한 아이템을 먼저 시도합니다. 음식은 게임의 식사 주문으로 가방에서 찾습니다. 입력한 음식이 먼저이고, 그다음은 가장 새로운 음식입니다. 회색 알림을 켜면 다 떨어진 분류도 클릭 동작 없이 계속 표시됩니다. 암살은 맹독을, 무법과 잠행은 순간 효과 독을 우선합니다. 용 담금질 칼날을 배우면 분류마다 독 두 개를 쓸 수 있습니다. 기름은 장착한 무기에 사용하며, 알고 있는 주술사 또는 성기사 무기 강화가 있으면 자동 기름은 제외됩니다.")
