T("Mapko uses Modern plates, Medium size and the same bar dimensions on Retail and Forever. Guild names and titles also affect names in the world. Bind Toggle friendly NPC nameplates under MSUF Suite in Blizzard Key Bindings. Import protection keeps your current nameplates when importing a full Suite profile; explicit nameplate imports still replace them.", "Mapko는 본 서버와 Forever에서 현대식 이름표, 중간 크기, 동일한 막대 크기를 사용합니다. 길드 이름과 칭호는 필드의 이름 표시에도 영향을 줍니다. 블리자드 단축키 설정의 MSUF Suite에서 아군 NPC 이름표 전환 키를 지정하세요. 가져오기 보호는 전체 Suite 프로필을 가져올 때 현재 이름표를 유지합니다. 이름표를 직접 가져오면 기존 설정을 교체합니다.")
