T("Observed enemies adds up the enemy forces of the living enemies in combat that you see as a nameplate or target, and the total they would bring. Enemies that give no forces count as zero; while the client keeps a value hidden, the line shows -- instead of a guess. Enemies out of sight are not counted.", "관측한 적은 이름표나 대상으로 보이는, 전투 중인 살아 있는 적의 병력 진척도를 더하고 그 적들이 채울 합계를 보여 줍니다. 병력 진척도를 주지 않는 적은 0으로 계산하며, 클라이언트가 값을 숨기는 동안에는 추정 대신 --를 표시합니다. 보이지 않는 적은 계산하지 않습니다.")
