T("Only containers newly acquired after enabling this helper are opened. It waits for combat to end, opens one at a time, and leaves them to you while you hold Shift or a loot window or a window that gives item use another meaning is open: merchant, bank, guild bank, mail, trade, auction house, scrapper, socket, upgrade and similar. Warbound containers stay unopened unless you allow them; profiles that used this helper before keep opening them. Midnight Artisan payouts can wait while your Shard of Dundun is capped.", "이 기능을 켠 뒤 새로 얻은 상자만 엽니다. 전투가 끝나기를 기다렸다가 한 번에 하나씩 열며, Shift를 누르고 있거나 전리품 창 또는 아이템 사용의 의미를 바꾸는 창(상인, 은행, 길드 은행, 우편, 거래, 경매장, 분해기, 보석 홈, 업그레이드 등)이 열려 있으면 직접 열도록 남겨 둡니다. 전투부대 상자는 허용하지 않는 한 열지 않으며, 이전부터 이 기능을 쓰던 프로필은 계속 엽니다. 둔둔의 조각이 한도에 도달한 동안에는 한밤 장인 보상을 보류할 수 있습니다.")
T("Only in an active Delve and outside combat: if the player choice has exactly one enabled spell option, one button and no confirmation, MSUF selects it once. Other choices remain manual.", "진행 중인 구렁에서 전투 중이 아닐 때에만, 플레이어 선택지에 사용할 수 있는 주문이 정확히 하나이고 버튼도 하나이며 확인창이 없으면 MSUF가 한 번 선택합니다. 다른 선택지는 직접 선택해야 합니다.")
T("Only inside instances", "인스턴스 안에서만")
