T("Opens your character window, on the tab you used last, when an item upgrade merchant opens. It closes only a window this helper opened and waits for the end of combat to open or close it.", "아이템 업그레이드 상인이 열리면 마지막으로 사용한 탭으로 캐릭터 창을 엽니다. 이 도우미가 연 창만 닫으며, 전투가 끝난 뒤에 창을 열거나 닫습니다.")
T("Optional Blizzard settings for chat, map, sound and low-health or alternate screen flashes. MSUF restores the previous value when you turn a choice or this helper off. Changes you make yourself in Blizzard settings while this helper runs are respected.", "채팅, 지도, 소리, 체력 저하 또는 대체 화면 깜박임에 대한 선택적 블리자드 설정입니다. MSUF는 선택 항목을 끄거나 이 도우미를 끄면 이전 값을 복원합니다. 이 도우미가 실행되는 동안 블리자드 설정에서 직접 변경한 사항은 존중됩니다.")
T("Optional artwork and spacing controls. Use MSUF Edit Mode for position, nudging, reset, undo and redo.", "선택 사항인 아트워크 및 간격 설정입니다. 위치, 미세 조정, 초기화, 실행 취소, 다시 실행은 MSUF 편집 모드를 사용하세요.")
T("Optional shortcuts for tutorials, item deletion and screenshot notices.", "튜토리얼, 아이템 삭제 및 스크린샷 알림을 위한 선택 기능입니다.")
