T("Pick the places where reminders may show; arenas and battlegrounds never show them. Before a keystone starts, buffs can be asked to last the dungeon's timer or a number of minutes; once the key starts, the normal warning time applies again. One scheduled wakeup handles the next expiry.", "알림이 표시될 수 있는 곳을 고르세요. 투기장과 전장에서는 표시되지 않습니다. 쐐기돌 시작 전에는 강화 효과가 던전 타이머나 정한 시간(분)만큼 유지되도록 요구할 수 있으며, 쐐기돌이 시작되면 일반 경고 시간이 다시 적용됩니다. 예약된 한 번의 확인이 다음 만료를 처리합니다.")
