T("Replaces the merchant's pages with one list; scroll it with the mouse wheel or the bar. Right-click buys, left-click picks an item up and Shift-click asks for a quantity; linking and previewing work as usual. Purchases paid with currencies or items, or costing at least 150 gold, ask for confirmation first. The buyback tab keeps Blizzard's layout. Drop or click an item from your bags onto the list to sell it; one you can still refund asks whether to refund it.", "상인의 페이지를 하나의 목록으로 바꿉니다. 마우스 휠이나 막대로 스크롤하세요. 오른쪽 클릭은 구매, 왼쪽 클릭은 아이템 집기, Shift 클릭은 수량을 묻습니다. 링크와 미리보기는 평소처럼 작동합니다. 화폐나 아이템으로 지불하거나 150골드 이상인 구매는 먼저 확인을 요청합니다. 되사기 탭은 블리자드 레이아웃을 유지합니다. 가방의 아이템을 목록에 놓거나 클릭하면 판매합니다. 아직 환불할 수 있는 아이템은 환불할지 묻습니다.")
T("Report junk sale requests in chat", "잡동사니 판매 요청을 대화창에 알림")
T("Reports group member deaths in chat during combat.", "전투 중 파티원의 사망을 대화창에 알립니다.")
T("Reports the first observed death of each group member during combat. Local chat, a screen notice and a sound can be selected separately. Simultaneous deaths share one sound. Optionally include your own death. The listener is active only while you are grouped and in combat.", "전투 중 각 파티원의 첫 번째 감지된 사망을 알립니다. 로컬 대화, 화면 알림, 소리를 각각 선택할 수 있습니다. 동시 사망에는 소리를 한 번만 재생합니다. 자신의 사망도 포함할 수 있습니다. 파티에 속해 전투 중일 때만 감지합니다.")
