T("Restores this bar's default spells and buffs for your specialization. Other bars and specializations stay as they are. You can undo it.", "전문화에 맞는 이 바의 기본 주문과 강화 효과를 복원합니다. 다른 바와 전문화는 그대로 유지됩니다. 실행 취소할 수 있습니다.")
