T("Resurrection offers", "부활 제안")
T("Retail Druids only. Every incoming whisper in combat is a possible Innervate cue; message text cannot be inspected reliably during chat lockdown. The alert waits for a publicly known Innervate cooldown, or shows a generic cue when readiness is unavailable. A preferred target can be outlined on an MSUF group frame resolved outside combat. MSUF Edit Mode previews the alert and edits its position and size.", "본 서버 드루이드 전용입니다. 대화 잠금 중에는 메시지 내용을 안정적으로 확인할 수 없으므로, 전투 중 들어오는 모든 귓속말을 정신 자극 요청일 수 있는 신호로 간주합니다. 알림은 공개적으로 알 수 있는 정신 자극 재사용 대기시간을 기다리며, 준비 상태를 알 수 없으면 일반 알림을 표시합니다. 선호 대상은 전투 밖에서 확인된 MSUF 그룹 프레임에 외곽선으로 표시할 수 있습니다. MSUF 편집 모드에서 알림을 미리 보고 위치와 크기를 편집합니다.")
T("Retail only. Shows while Skyriding is available, or only in flight if selected. Choose bars or Blizzard Vigor gems; gem scale and a refill sound are optional. Separate bar heights, Surge icon size and speed-value offsets are under Text and bars. MSUF Edit Mode previews the HUD. Unknown charge values display as dashes.", "Retail 전용입니다. 하늘비행을 사용할 수 있을 때 표시하거나 선택하면 비행 중에만 표시합니다. 막대 또는 블리자드 활력 보석을 선택하며 보석 크기와 충전 소리는 선택 사항입니다. 개별 막대 높이, 쇄도 아이콘 크기 및 속도 값 간격은 ‘텍스트 및 막대’에 있습니다. MSUF 편집 모드는 HUD 미리 보기를 표시합니다. 알 수 없는 충전 값은 대시로 표시합니다.")
T("Return to the current fight when combat starts", "전투 시작 시 현재 전투로 돌아가기")
T("Returns this specialization to its short raid essentials list. Your other bars and specializations stay as they are. You can undo it.", "이 전문화를 간단한 공격대 필수 목록으로 되돌립니다. 다른 바와 전문화는 그대로 유지됩니다. 실행 취소할 수 있습니다.")
