T("Selected currencies appear above the bag footer. Click Gold history for recorded character balances and 30 days of this character's income and spending, by local date. Other characters show their last recorded balance. The history starts when enabled and does not reconstruct earlier transactions; Clear saved character gold removes the history and the balances.", "선택한 화폐는 가방 하단 정보 위에 표시됩니다. 골드 내역을 클릭하면 기록된 캐릭터 잔액과 이 캐릭터의 30일간 수입과 지출을 현지 날짜별로 볼 수 있습니다. 다른 캐릭터는 마지막으로 기록된 잔액을 표시합니다. 기록은 기능을 켠 시점부터 시작되며 이전 거래는 복원하지 않습니다. 저장된 캐릭터 골드 기록 삭제는 내역과 잔액을 모두 지웁니다.")
T("Selected data", "선택한 정보")
