T("Show subzone below zone", "지역 아래에 하위 지역 표시")
T("Show target damage on mouseover (spells when unavailable)", "마우스오버 시 대상별 피해 표시 (불가능하면 주문별)")
T("Show temporary weapon enchant ID", "임시 무기 인챈트 ID 표시")
T("Show tenths of a second", "0.1초 단위 표시")
T("Show the Mythic+ card", "신화+ 카드 표시")
T("Show the active Burning Rush aura during combat through Blizzard's native aura container.", "Blizzard의 기본 오라 컨테이너를 통해 전투 중에 활성 Burning Rush 오라를 표시합니다.")
T("Show the active talent build and loot specialization on ready checks or instance entry, with an optional saved expectation.", "전투 준비 확인이나 인스턴스 입장 때 현재 특성 구성과 전리품 전문화를 표시합니다. 원하면 저장된 예상 구성을 함께 비교할 수 있습니다.")
T("Show the collapsible raid tools panel", "접을 수 있는 공격대 도구 패널 표시")
T("Show the drawer button only on mouseover", "마우스오버 시에만 서랍 버튼 표시")
T("Show the enemy forces bar", "적 병력 막대 표시")
T("Show the enemy forces text", "적 병력 글자 표시")
T("Show the global cooldown in its own circle instead of the ring", "전역 재사용 대기시간을 고리 대신 별도 원에 표시")
T("Show the global cooldown on icons", "아이콘에 전역 재사용 대기시간 표시")
T("Show the global cooldown swipe for this spell. Reset follows the global cooldown setting in Basics.", "이 주문에 전역 재사용 대기시간 회전 효과를 표시합니다. 초기화하면 기본 설정의 전역 재사용 대기시간 설정을 따릅니다.")
T("Show the icon only while the spell is on cooldown.", "주문이 재사용 대기 중일 때만 아이콘을 표시합니다.")
T("Show the item level on equipment sold by a merchant.", "상인이 판매하는 장비에 아이템 레벨을 표시합니다.")
T("Show the mana note for (seconds)", "마나 알림 표시 시간 (초)")
T("Show the minimap", "미니맵 표시")
T("Show the native WoW Token market price in Gold tooltips", "금화 툴팁에 기본 WoW 토큰 시세 표시")
T("Show the summary beside the character sheet", "캐릭터 창 옆에 요약 표시")
T("Show the swipe edge", "쓸어내기 가장자리 표시")
T("Show the target time of bosses still alive", "아직 살아 있는 보스의 목표 시간 표시")
T("Show this bar", "이 바 표시")
T("Show this bar first.", "먼저 이 바를 표시하세요.")
T("Show this category", "이 분류 표시")
T("Show time", "시간 표시")
T("Show time inside the timer bar", "타이머 막대 안에 시간 표시")
T("Show time to level", "레벨 업까지 남은 시간 표시")
T("Show tooltips", "툴팁 표시")
T("Show tracker heading", "추적기 제목 표시")
T("Show unit level", "유닛 레벨 표시")
T("Show unit titles", "유닛 칭호 표시")
T("Show upgrade threshold markers", "등급 상승 기준선 표시")
T("Show upgrade track and rank", "강화 단계와 등급 표시")
T("Show used bag space as percent", "사용한 가방 공간을 백분율로 표시")
T("Show versatility", "유연성 표시")
T("Show weather", "날씨 표시")
T("Show weather as text, an icon, or both. Choose Blizzard icons or original Forever artwork. The tooltip keeps the weather name when only the icon is shown.", "날씨를 텍스트, 아이콘 또는 둘 다로 표시합니다. 블리자드 아이콘이나 자체 제작한 Forever 디자인을 선택하세요. 아이콘만 표시해도 툴팁에는 날씨 이름이 표시됩니다.")
T("Show weekly reward item levels", "주간 보상 아이템 레벨 표시")
T("Show who each cast targets", "각 시전의 대상 표시")
T("Show windows", "창 표시")
T("Show your Bloodlust exhaustion or ready state while grouped.", "파티에 있을 때 자신의 피의 욕망 계열 탈진 또는 사용 가능 상태를 표시합니다.")
T("Show your owned item count, including bank and Warband bank, on item tooltips.", "아이템 툴팁에 은행, 전투부대 은행 등 보유 아이템 수를 표시합니다.")
T("Show your selected loot specialization in the Great Vault window.", "위대한 금고 창에 선택한 전리품 전문화를 표시합니다.")
T("Show zone", "지역 표시")
T("Shown value", "표시 값")
T("Shown windows: %d. Raise the number of windows to show this one.", "표시된 창: %d개. 이 창을 표시하려면 창 개수를 늘리세요.")
T("Shows Blizzard's shared battle resurrection charges in an active Mythic+ run or raid encounter. The icon counts down to the next charge using Blizzard's cooldown display. Hidden when the shared pool is unavailable. MSUF Edit Mode previews the display and edits X, Y, width, height and scale.", "진행 중인 신화+ 또는 공격대 우두머리 전투에서 블리자드의 공유 전투 부활 충전을 표시합니다. 아이콘은 블리자드 재사용 대기시간 표시로 다음 충전까지 카운트다운합니다. 공유 충전을 사용할 수 없으면 숨겨집니다. MSUF 편집 모드에서 표시를 미리 보고 X, Y, 너비, 높이, 배율을 편집합니다.")
T("Shows an approximate range to your current target from the game's range checks of spells you know; values include the target's hitbox, and dashes mean that no known spell can tell. Write the text with {range} and {unit}. The estimate can sit below the target frame, following it when the frame moves, or anywhere on screen; MSUF Edit Mode moves both placements.", "알고 있는 주문에 대한 게임의 사거리 확인으로 현재 대상까지의 대략적인 거리를 표시합니다. 값에는 대상의 피격 범위가 포함되며, 대시는 아는 주문으로 알 수 없다는 뜻입니다. {range}와 {unit}으로 문구를 정합니다. 추정치는 대상 프레임 아래에 두어 프레임이 움직이면 따라가게 하거나 화면 어디에나 둘 수 있으며, MSUF 편집 모드에서 두 위치를 모두 옮길 수 있습니다.")
T("Shows incoming damage and healing for you or your vehicle. Blizzard's own combat text is hidden while enabled and restored when disabled. Move the display in MSUF Edit Mode. During heavy bursts the oldest of the visible messages is replaced. The game may keep amounts private, so messages are never combined or filtered by their value.", "자신이나 탈것이 받은 피해와 치유를 표시합니다. 활성화된 동안 블리자드 전투 메시지가 숨겨지고 비활성화하면 복원됩니다. MSUF 편집 모드에서 위치를 옮기세요. 메시지가 많이 발생하면 가장 오래된 표시 메시지를 교체합니다. 게임이 수치를 숨길 수 있으므로 메시지를 합산하거나 수치에 따라 필터링하지 않습니다.")
T("Shows item levels on merchant equipment when Blizzard has loaded its item data. Buyback items and items without an item level stay unchanged.", "블리자드가 아이템 데이터를 불러오면 상인 장비에 아이템 레벨을 표시합니다. 되사기 아이템과 아이템 레벨이 없는 아이템은 그대로 둡니다.")
T("Shows the current loot specialization when you open the Great Vault. Updates if you change loot specialization while the window is open.", "위대한 금고를 열면 현재 전리품 전문화를 표시합니다. 창이 열려 있는 동안 전리품 전문화를 바꾸면 갱신됩니다.")
T("Shows the lowest equipped durability below your chosen threshold, outside combat. MSUF Edit Mode shows a sample even when your gear is repaired. Its popup edits X, Y, width, height and scale.", "전투 중이 아닐 때, 착용 장비의 가장 낮은 내구도가 선택한 기준보다 낮으면 표시합니다. MSUF 편집 모드에서는 장비가 수리된 상태여도 예시를 표시합니다. 팝업에서 X, Y, 너비, 높이, 배율을 편집합니다.")
T("Shows the number you own, including your bank and Warband bank, when the item tooltip has a public item ID. Optionally separate storage locations. Empty counts are omitted.", "아이템 툴팁에 공개 아이템 ID가 있으면 은행과 전투부대 은행을 포함한 보유 수량을 표시합니다. 보관 장소별로 나누어 표시할 수도 있습니다. 수량이 0인 곳은 생략합니다.")
T("Shows the total durability of your gear on the character model, moved by the two offsets, and crops the edges of the gear slot icons on your character sheet and in the Inspect window.", "장비의 전체 내구도를 캐릭터 모델 위에 두 오프셋만큼 옮겨 표시하고, 캐릭터 창과 살펴보기 창의 장비 슬롯 아이콘 가장자리를 잘라냅니다.")
T("Shows up to three extra compact notices for Blizzard personal item-loot toasts. Filter by minimum quality, mount or pet items, and optionally up to 100 item IDs. Native Blizzard notices remain visible; ordinary bag additions without a toast are not included.", "블리자드가 개인 아이템 획득 알림을 표시하면 작은 추가 알림을 최대 세 개 보여줍니다. 최소 품질, 탈것 또는 애완동물 아이템, 최대 100개 아이템 ID로 걸러낼 수 있습니다. 블리자드 기본 알림은 그대로 남습니다. 획득 알림 없이 가방에 들어온 일반 아이템은 포함하지 않습니다.")
T("Shows your current talent build and loot specialization on ready checks, when a dungeon queue pops, or when you enter an instance. It never changes your talents or loot spec.", "전투 준비 확인, 던전 입장 대기열 알림 또는 인스턴스 입장 때 현재 특성 구성과 전리품 전문화를 표시합니다. 특성이나 전리품 전문화를 자동으로 변경하지 않습니다.")
T("Shows your most recent successful spells. Standard rows have an icon, name and marker; Icons only is a compact vertical icon column. Display width applies to standard rows; icon width follows row height in the icon preset. Position and anchor are set in MSUF Edit Mode, which shows sample actions. The list stops listening while disabled. Spells whose details the client keeps private cannot appear.", "최근 성공적으로 사용한 주문을 표시합니다. 표준 행에는 아이콘, 이름과 표시기가 있으며 '아이콘만' 사전 설정은 세로로 정렬된 작은 아이콘 열입니다. 표시 너비는 표준 행에 적용되고 아이콘 사전 설정의 너비는 행 높이를 따릅니다. MSUF 편집 모드에서 위치와 기준점을 정하고 예시 행동을 볼 수 있습니다. 비활성화하면 주문 이벤트를 더 이상 수신하지 않습니다. 클라이언트가 세부 정보를 비공개로 유지하는 주문은 표시할 수 없습니다.")
T("Shows your own Bloodlust exhaustion while in a group, or a ready state if you prefer. Relevant player aura changes update it; MSUF Edit Mode moves it and previews the locked state.", "파티에 있을 때 자신의 피의 욕망 계열 효과로 인한 탈진 상태를 표시합니다. 원하면 사용 가능 상태도 표시할 수 있습니다. 관련 오라가 바뀔 때 갱신되며 MSUF 편집 모드에서 위치를 옮기고 잠금 상태를 미리 볼 수 있습니다.")
T("Shuffle displayed items", "표시 아이템 순서 섞기")
