T("Size and look of aura timer bars and cooldowns displayed as timer bars. Stack-filled buff bars use the native stack binding; stack glows remain available on icon and duration views.", "오라 시간 막대 및 시간 막대로 표시되는 재사용 대기시간의 크기와 모양입니다. 중첩으로 채우는 강화 효과 막대는 게임의 중첩 바인딩을 사용합니다. 중첩 반짝임은 아이콘 및 지속시간 보기에서 계속 사용할 수 있습니다.")
