T("Skin high-visibility HUD surfaces while Blizzard keeps positioning, data and actions.", "잘 보이는 HUD 표면에 스킨을 적용하고 위치, 데이터, 동작은 블리자드가 그대로 담당합니다.")
T("Skin look", "스킨 외형")
T("Skin look unavailable", "Skin 외형을 사용할 수 없음")
T("Skin only Blizzard's own personal mana and alternate-power status bars. Blizzard still owns their values, fill and visibility. Class-specific resource points retain Blizzard's layout. Select and drag the power bar in the personal preview.", "블리자드 자체 개인 마나 및 보조 자원 상태 바에만 스킨을 적용합니다. 수치, 채우기, 표시 여부는 계속 블리자드가 처리합니다. 직업별 자원 점수는 블리자드 배치를 유지합니다. 개인 미리보기에서 자원 바를 선택해 끌 수 있습니다.")
T("Skin preview", "스킨 미리보기")
T("Skin profile name already exists or skin engine is unavailable", "스킨 프로필 이름이 이미 있거나 스킨 엔진을 사용할 수 없습니다")
T("Skin profile unavailable", "스킨 프로필을 사용할 수 없음")
T("Skin refresh is blocked during combat.", "전투 중에는 스킨을 새로 고칠 수 없습니다.")
T("Skin the Blizzard Micro Bar", "블리자드 마이크로 메뉴에 스킨 적용")
T("Skinning", "스킨 적용")
T("Skip cinematic confirmation", "시네마틱 확인 건너뛰기")
T("Skipping ends Blizzard's movie or cinematic from addon code, which can rarely cause an \"Interface action blocked\" message later.", "건너뛰기는 애드온 코드에서 블리자드의 동영상이나 시네마틱을 끝내므로, 드물게 나중에 \"인터페이스 동작 차단\" 메시지가 나타날 수 있습니다.")
T("Skull", "해골")
T("Skurri", "Skurri 글꼴")
T("Skyriding HUD", "하늘비행 HUD")
