T("Slot sizing", "칸 크기 조정")
T("Slug", "Slug")
T("Smoked near-black glass with crisp hairlines and restrained class-color focus.", "선명한 가는 선과 절제된 직업 색상 포커스를 갖춘, 검정에 가까운 연기 유리.")
T("Smooth", "부드럽게")
