T("Social, mail and guild", "소셜, 우편 및 길드")
T("Sockets: %d filled / %d existing, %d empty.", "보석 홈: %d개 장착 / %d개 있음, %d개 비어 있음.")
T("Soft", "은은하게")
T("Soft border", "부드러운 테두리")
T("Soft fill", "부드러운 채우기")
T("Soft target", "소프트 타겟")
T("Soft target icon", "소프트 타겟 아이콘")
T("Soft target icon on nameplates", "이름표의 소프트 타겟 아이콘")
T("Soft violet-black panels with wide curves.", "넓은 곡선의 부드러운 보랏빛 검정 패널.")
T("Soft: enemy / interact", "소프트: 적 / 상호작용")
T("Solid", "선명하게")
T("Solid fill", "단색 채우기")
T("Solo", "솔로")
T("Some chat colors could not be restored", "일부 채팅 색상을 복원할 수 없습니다")
T("Some checks are unverified. Missing-enchant rules cover level-90 Midnight gear. Sockets count existing sockets, not potential seasonal additions; this is not a best-in-slot verdict.", "일부 점검은 확인되지 않았습니다. 마법부여 누락 규칙은 Midnight 90레벨 장비를 기준으로 합니다. 보석 홈은 시즌에 추가될 수 있는 홈이 아니라 현재 있는 홈만 셉니다. 최적 장비 판정이 아닙니다.")
T("Some services cannot be distinguished; train them individually.", "일부 서비스는 구별할 수 없습니다. 개별적으로 훈련하십시오.")
T("Sort Mythic+ applications by average member dungeon score when every score is available.", "모든 점수를 확인할 수 있을 때 신화+ 신청 그룹의 구성원 평균 던전 점수로 정렬합니다.")
T("Sort applicants for your own Mythic+ listing by their average member score, highest first. Ties keep Blizzard's order. If any score is missing or restricted, the native order remains. The closed list is untouched.", "내 신화+ 파티 신청자를 구성원 평균 점수가 높은 순서로 정렬합니다. 평균이 같으면 블리자드 순서를 유지합니다. 점수가 없거나 제한되면 원래 순서를 유지합니다. 창이 닫혀 있을 때는 목록을 변경하지 않습니다.")
