T("Switch between native tabs, combined bank, combined warbank and shared categories with the button below the bank window. Shared categories include accessible character and warbank tabs. Manage bank tabs returns to Blizzard purchases, deposits and tab settings. Every slot keeps its own item action and bank stacks are never merged; clicking a warband item selects Blizzard's Warband Bank tab first, and a refundable item asks before it enters the warband bank.", "은행 창 아래의 버튼으로 기본 탭, 통합 은행, 통합 전투부대 은행, 공유 분류를 전환합니다. 공유 분류에는 접근 가능한 캐릭터 및 전투부대 은행 탭이 포함됩니다. 은행 탭 관리를 누르면 블리자드의 탭 구매, 입금 및 설정 화면으로 돌아갑니다. 각 칸은 고유한 아이템 동작을 유지하며 은행 묶음은 합치지 않습니다. 전투부대 아이템을 클릭하면 먼저 블리자드의 전투부대 은행 탭이 선택되며, 환불 가능한 아이템은 전투부대 은행에 들어가기 전에 확인을 묻습니다.")
T("Switch each bar on or off here. Turning it back on restores its previous visibility mode. Select Layout to customize the bar selected above.", "각 단축바를 여기서 켜거나 끄세요. 다시 켜면 이전 표시 방식이 복원됩니다. 위에서 선택한 단축바를 조정하려면 배치를 선택하세요.")
