T("The Suite Cooldown manager page (CDM) shows Blizzard's tracked cooldowns and buffs as bars you arrange and style freely.", "Suite의 재사용 대기시간 관리자(CDM) 페이지는 블리자드에서 추적하는 재사용 대기시간과 강화 효과를 자유롭게 배치하고 꾸밀 수 있는 막대로 표시합니다.")
T("The Suite Minimap page styles the minimap itself: size, shape, border, zoom, buttons and info texts. MSUF's own minimap icon is under Miscellaneous.", "Suite의 미니맵 페이지에서 미니맵 자체의 크기, 모양, 테두리, 확대/축소, 버튼, 정보 텍스트를 설정할 수 있습니다. MSUF의 미니맵 아이콘 설정은 기타에 있습니다.")
T("The Suite Nameplates page styles Blizzard's enemy and friendly nameplates. MSUF's aura filters only decide whether nameplate-only auras show on MSUF frames.", "Suite의 이름표 페이지는 블리자드의 적 및 아군 이름표 모양을 설정합니다. MSUF의 오라 필터는 이름표 전용 오라를 MSUF 프레임에 표시할지만 결정합니다.")
T("The Suite draws its own tracker and hides Blizzard's while it runs. Entries are sorted into groups: the focused quest, campaign and important quests, quests ready to hand in, regular quests, world quests, nearby bonus objectives, scenario and delve steps, and tracked achievements. In a raid it can hide completely, only while a boss is engaged, or pause the regular list during any raid fight; the encounter view keeps running then. Quest symbols come as Suite letters or as Blizzard's icons, and the heading line can be switched off. The key binding Use tracked quest item uses the focused quest's item, else the first usable one, and picks a new item only outside combat. Left-click a group name to fold it or a quest to open its log entry; right-click for more actions.", "Suite는 자체 추적기를 그리고 작동하는 동안 블리자드 추적기를 숨깁니다. 항목은 집중 퀘스트, 캠페인 및 중요 퀘스트, 완료 보고 가능 퀘스트, 일반 퀘스트, 전역 퀘스트, 주변 보너스 목표, 시나리오 및 구렁 단계, 추적 업적의 그룹으로 정렬됩니다. 공격대에서는 완전히 숨기거나, 우두머리 전투 중에만 숨기거나, 공격대 전투 중 일반 목록을 일시 중지할 수 있으며, 이때 전투 보기는 계속 작동합니다. 퀘스트 기호는 Suite 문자 또는 블리자드 아이콘으로 표시하며, 제목 줄은 끌 수 있습니다. 단축키 '추적 퀘스트 아이템 사용'은 집중 퀘스트의 아이템을, 없으면 첫 번째 사용 가능한 아이템을 사용하며, 새 아이템은 전투 밖에서만 고릅니다. 그룹 이름을 왼쪽 클릭하면 접고 퀘스트를 클릭하면 퀘스트 기록이 열리며, 오른쪽 클릭하면 다른 작업을 할 수 있습니다.")
T("The Suite frames Blizzard's original Micro Buttons. Their artwork, clicks, tooltips, enabled states and notifications stay native. Queue and FPS indicators stay at Blizzard's Edit Mode position. No recurring MSKIN update runs.", "Suite가 블리자드의 원래 마이크로 메뉴 버튼에 테두리를 씌웁니다. 아트워크, 클릭, 툴팁, 활성 상태, 알림은 기본 그대로입니다. 대기열 및 FPS 표시기는 블리자드 편집 모드에서 정한 위치에 남습니다. 반복되는 MSKIN 갱신은 없습니다.")
T("The Suite look gives Blizzard's dialogs a dark panel, and the Suite font sets their text font and size; each works alone, and without them dialogs keep Blizzard's look and fonts. A minimum height makes short dialogs taller once Blizzard has sized them; 0 keeps Blizzard's height. A custom position moves the first dialog and the ones Blizzard stacks below it; place it and set the height in MSUF Edit Mode.", "Suite 모양은 블리자드 대화 상자에 어두운 패널을 주고, Suite 글꼴은 문자의 글꼴과 크기를 정합니다. 각각 따로 쓸 수 있으며, 둘 다 없으면 대화 상자는 블리자드 모양과 글꼴을 유지합니다. 최소 높이는 블리자드가 크기를 정한 뒤 짧은 대화 상자를 더 높게 만들며, 0은 블리자드 높이를 유지합니다. 사용자 위치는 첫 대화 상자와 블리자드가 그 아래에 쌓는 대화 상자를 옮깁니다. MSUF 편집 모드에서 배치하고 높이를 정하세요.")
T("The Suite skin engine is unavailable.", "Suite 스킨 엔진을 사용할 수 없습니다.")
T("The chosen profile supplies all settings. Toggle which Suite modules are enabled in it.", "선택한 프로필이 모든 설정을 제공합니다. 그 프로필에서 활성화할 Suite 모듈을 켜고 끄세요.")
T("The class buff is included only when your character knows it. Enter self-buff spell IDs separated by spaces or commas. For a consumable, enter item ID:aura ID; separate pairs with commas. Up to 12 total reminders are shown. Weapon enchant items use the main-hand or off-hand enchant state.", "직업 강화 효과는 캐릭터가 알고 있을 때만 포함됩니다. 자가 강화 효과 주문 ID를 공백이나 쉼표로 구분해 입력하세요. 소모품은 아이템 ID:오라 ID 형식으로 입력하고, 여러 쌍은 쉼표로 구분하세요. 알림은 최대 12개까지 표시됩니다. 무기 마법부여 아이템은 주 장비 또는 보조 장비의 마법부여 상태를 사용합니다.")
T("The combined bag and reagent bag use a Suite panel with a distinct header, border, and accent line. Set background opacity to 0 for a transparent window; item slots stay visible.", "통합 가방과 재료 가방은 구분되는 머리글, 테두리, 포인트 선이 있는 Suite 패널을 사용합니다. 배경 불투명도를 0으로 설정하면 창이 투명해지며, 아이템 칸은 계속 보입니다.")
T("The combined bag setting is protected on this client", "이 클라이언트에서는 통합 가방 설정이 보호되어 있음")
T("The configuration cannot be opened during combat.", "전투 중에는 설정을 열 수 없습니다.")
T("The cooldown manager is not loaded.", "재사용 대기시간 관리자를 불러오지 않았습니다.")
T("The cooldown manager needs an update. Reload the interface.", "재사용 대기시간 관리자를 갱신해야 합니다. 인터페이스를 다시 불러오세요.")
T("The cooldown manager was reset: settings, spell lists and spell options.", "재사용 대기시간 관리자를 초기화했습니다: 설정, 주문 목록, 주문 옵션.")
T("The countdown turns to the warning color below this many seconds. All bars: the Text section's setting.", "남은 시간이 이 초 수 미만이 되면 카운트다운이 경고 색상으로 바뀝니다. 모든 바: 텍스트 섹션의 설정.")
T("The dark sweep over the icon while it counts down.", "카운트다운 중 아이콘 위를 덮는 어두운 쓸어내기 효과입니다.")
T("The default font follows MSUF Fonts while the default size follows Blizzard's chat size. Choose Blizzard chat font to keep its own face. Slug has no shadow.", "기본 글꼴은 MSUF 글꼴을 따르고, 기본 크기는 블리자드 대화 크기를 따릅니다. 블리자드 고유의 글꼴을 유지하려면 '블리자드 대화창 글꼴'을 선택하세요. Slug에는 그림자가 없습니다.")
T("The dungeon's timer", "던전 타이머")
T("The engine remains dormant until a lifecycle event or an explicit user action requires work.", "엔진은 수명 주기 이벤트나 사용자의 명시적인 동작이 작업을 요구할 때까지 대기합니다.")
T("The global cooldown can leave the ring for a fixed circle of its own size and opacity, shown next to casts. Place it in MSUF Edit Mode; its button there works while this choice is on.", "전역 재사용 대기시간을 고리에서 빼내 크기와 불투명도를 따로 정한 고정 원에 표시할 수 있으며, 시전과 함께 보입니다. MSUF 편집 모드에서 배치하며, 이 선택이 켜져 있을 때 그곳의 버튼이 작동합니다.")
T("The header shows the meter and fight. Its buttons change the meter and fight directly in the window.", "머리글에는 측정기와 전투가 표시됩니다. 머리글 버튼으로 창에서 바로 측정기와 전투를 바꿀 수 있습니다.")
T("The keystone notice remains local. The optional group announcement forwards only Blizzard's confirmed reset message immediately after your own reset request, while you are group leader. Failed attempts and resets by other players are not announced.", "쐐기돌 알림은 로컬에만 표시됩니다. 선택적 파티 알림은 자신이 파티장일 때 직접 요청한 초기화 직후 블리자드가 확인한 초기화 메시지만 전달합니다. 실패한 시도나 다른 플레이어의 초기화는 알리지 않습니다.")
T("The macro builder is available only in Retail", "Retail에서만 사용할 수 있습니다.")
T("The macro exceeds the 255-character limit", "매크로가 255자 제한을 초과했습니다.")
T("The map grows or shrinks to the chosen width and height while the pointer is over it, then returns to its normal size. A circular map keeps its height equal to its width.", "마우스 포인터를 올리면 지도가 선택한 너비와 높이로 커지거나 작아지고, 포인터가 벗어나면 원래 크기로 돌아옵니다. 원형 지도는 높이를 너비와 같게 유지합니다.")
T("The merchant's offers changed; nothing was bought.", "상인의 판매 목록이 바뀌어 아무것도 구매하지 않았습니다.")
T("The merchant's whole stock in one scrolling list with prices, quality colors and item levels.", "상인의 모든 상품을 가격, 품질 색상, 아이템 레벨과 함께 하나의 스크롤 목록으로 보여줍니다.")
T("The minutes below", "아래의 시간(분)")
T("The mouse wheel zooms the map. Middle-click runs the chosen action; left and right clicks keep working as usual.", "마우스 휠로 지도를 확대/축소합니다. 가운데 클릭은 선택한 동작을 실행하며, 왼쪽 및 오른쪽 클릭은 평소처럼 작동합니다.")
T("The native input box keeps autocomplete, links and chat commands.", "기본 입력창은 자동 완성, 링크, 대화 명령어를 그대로 유지합니다.")
T("The normal warning time", "일반 경고 시간")
T("The optional glyph layer changes appearance while Blizzard keeps clicks, tooltips, enabled states and notifications. Queue and FPS indicators stay at Blizzard's Edit Mode position. No recurring MSKIN update runs.", "선택형 기호 레이어가 외형을 바꾸고 클릭, 툴팁, 활성 상태, 알림은 블리자드가 유지합니다. 대기열 및 FPS 표시기는 블리자드 편집 모드에서 정한 위치에 남습니다. 반복되는 MSKIN 갱신은 없습니다.")
T("The options module could not be loaded: %s", "옵션 모듈을 불러오지 못했습니다: %s")
T("The options module did not finish initializing.", "옵션 모듈의 초기화가 완료되지 않았습니다.")
T("The party table grows in steps: characters with build and score, then the combat figures of Blizzard's damage meter, then the loot seen in chat. Each character keeps its latest runs; open the newest here or with /msufruns and step through older ones. Deleting a run asks for a second click. The card can wait until you close the chest's loot window.", "파티 표는 단계별로 늘어납니다. 전문화와 점수가 있는 캐릭터, 그다음 블리자드 피해 미터의 전투 수치, 그다음 대화창에서 확인한 전리품입니다. 캐릭터마다 최근 공략을 보관하며, 여기서 또는 /msufruns로 최신 공략을 열고 이전 공략을 넘겨 볼 수 있습니다. 공략을 삭제하려면 한 번 더 클릭해야 합니다. 상자 전리품 창을 닫을 때까지 카드를 미룰 수 있습니다.")
T("The preview and every section below edit this bar. Shared custom groups start with a separate list for explicit spell, aura and item IDs; disabling sharing restores the existing per-specialization list.", "미리보기와 아래의 모든 섹션은 이 바를 편집합니다. 공유 사용자 그룹은 직접 지정한 주문, 오라 및 아이템 ID의 별도 목록으로 시작합니다. 공유를 끄면 기존 전문화별 목록을 복원합니다.")
T("The preview needs the cooldown manager.", "미리보기에는 재사용 대기시간 관리자가 필요합니다.")
T("The quick switch above remembers this mode when you turn the bar off. Choose Never to keep it hidden.", "위의 빠른 스위치로 바를 끄면 이 방식이 기억됩니다. 계속 숨기려면 '안 함'을 선택하세요.")
T("The settings you change most. Attach the bar to another bar or to your player frame to keep them together; the gap is the space between them. Center keeps the first cooldown icon in the middle and adds the next icons right, left, right, left. Visible buffs stay compact; on a horizontal mixed bar, player and target buffs grow outward from the center on one row.", "가장 자주 바꾸는 설정입니다. 바를 다른 바나 플레이어 프레임에 붙이면 함께 유지되며, 간격은 둘 사이의 거리입니다. '가운데'는 첫 재사용 대기시간 아이콘을 가운데에 두고 다음 아이콘을 오른쪽, 왼쪽, 오른쪽, 왼쪽 순으로 추가합니다. 표시된 강화 효과는 촘촘하게 유지되며, 가로형 혼합 바에서는 플레이어와 대상의 강화 효과가 한 줄에서 가운데부터 바깥쪽으로 늘어납니다.")
T("The socket window is available only in Retail", "Retail에서만 사용할 수 있습니다.")
T("The stack condition uses Glow at stacks and Stack comparison. Buff absence cannot drive a combat glow through the native aura-slot API.", "중첩 조건은 중첩 반짝임 기준과 중첩 비교를 사용합니다. 기본 오라 슬롯 API로는 강화 효과가 없을 때 전투 중 반짝임을 표시할 수 없습니다.")
T("Theme", "테마")
T("Theme-colored icon outline", "테마 색상 아이콘 외곽선")
T("These apply to every bar. The standalone assisted icon follows Blizzard's assisted combat highlight; enable that highlight in the game's Combat options. Its position is available in MSUF Edit Mode. Action bar presses show on cooldown icons only with the MSUF Suite action bars.", "모든 막대에 적용됩니다. 독립 보조 아이콘은 블리자드 전투 보조 강조 표시를 따릅니다. 게임의 전투 설정에서 해당 강조 표시를 켜세요. 위치는 MSUF 편집 모드에서 조정할 수 있습니다. 행동 단축바 누름 효과는 MSUF Suite 행동 단축바를 사용할 때만 재사용 대기시간 아이콘에 표시됩니다.")
T("These apply to every bar:", "모든 바에 적용되는 설정:")
T("These choices apply to this spell on every bar and specialization.", "이 설정은 모든 바와 전문화에서 이 주문에 적용됩니다.")
T("These settings apply to all bars until a bar uses its own style.", "이 설정은 바가 개별 스타일을 사용하기 전까지 모든 바에 적용됩니다.")
T("Thick outline", "굵은 외곽선")
T("Thick outline + SLUG", "굵은 외곽선 + SLUG")
T("Thick outline + shadow", "굵은 외곽선 + 그림자")
T("Thin", "얇게")
T("Thin ring", "얇은 고리")
T("This bar cannot be moved on its own right now.", "지금은 이 바를 따로 옮길 수 없습니다.")
T("This bar has no spells or items you added.", "이 바에 추가한 주문이나 아이템이 없습니다.")
T("This bar has no spells yet. Click to add some.", "이 바에 아직 주문이 없습니다. 클릭해 추가하세요.")
T("This bar is full.", "이 바가 가득 찼습니다.")
T("This bar is off.", "이 바는 꺼져 있습니다.")
T("This bar sits on Blizzard's Essential bar, which your MSUF frames follow. Move it in Blizzard's Edit Mode.", "이 바는 MSUF 프레임이 따르는 블리자드 필수 바 위에 있습니다. 블리자드 편집 모드에서 옮기세요.")
T("This bar takes the place of %s, which is off. Move that bar, or attach this one elsewhere.", "이 바는 꺼져 있는 %s의 자리를 대신합니다. 그 바를 옮기거나 이 바를 다른 곳에 붙이세요.")
T("This bar's own options are not used by the %s type; the settings below apply to every bar.", "이 바의 개별 옵션은 %s 종류에서 사용하지 않으며, 아래 설정은 모든 바에 적용됩니다.")
T("This category already holds 500 items. Remove one before adding another.", "이 분류에는 이미 아이템 500개가 있습니다. 다른 아이템을 추가하기 전에 하나를 제거하세요.")
T("This client has no combined bag setting", "이 클라이언트에는 통합 가방 설정이 없음")
T("This client has not been identified", "클라이언트를 확인할 수 없음")
T("This demon is not one you chose; summon another.", "선택한 악마가 아닙니다. 다른 악마를 소환하세요.")
T("This feature is available only in Retail", "이 기능은 Retail에서만 사용할 수 있습니다")
T("This finishes loading the selected Suite modules.", "선택한 Suite 모듈의 불러오기를 마칩니다.")
T("This purchase cannot be refunded.", "이 구매는 환불할 수 없습니다.")
T("This slot contains %d; clicking uses this physical stack.", "이 칸에는 %d개가 있으며, 클릭하면 이 실제 묶음을 사용합니다.")
T("Threat", "위협")
T("Threat lost / taking aggro", "위협 수준 잃음 / 어그로 획득 중")
T("Threat meter", "위협 측정기")
T("Threat meter (Forever)", "위협 측정기 (Forever)")
T("Threat points", "위협 수치")
T("Threat warning", "위협 수준 경고")
T("Three rows", "세 줄")
