T("Tick every demon you want out; demons your character has not learned yet can be ticked too. A summoned demon you left unticked gets a notice, as long as one of your ticked demons can be summoned. Another look of a demon counts as that demon once you have summoned it in that look.", "꺼내 두고 싶은 악마를 모두 선택하세요. 캐릭터가 아직 배우지 않은 악마도 선택할 수 있습니다. 선택하지 않은 악마를 소환하면, 선택한 악마 중 하나를 소환할 수 있는 동안 알림이 표시됩니다. 악마의 다른 모습은 그 모습으로 한 번 소환한 뒤부터 같은 악마로 취급됩니다.")
