T("Timestamps use Blizzard's chat setting across all chat windows. Copy is off by default; when enabled, move its button with X/Y, choose a message, then press Ctrl+C. The displayed timestamp is included when timestamps are on. The message tools leave the Combat Log alone (its own settings can add a timestamp to every line); its lines still wake the idle fade. Saved history belongs to this character.", "시간 표시는 모든 대화창에서 블리자드 대화 설정을 따릅니다. 복사는 기본적으로 꺼져 있으며, 켜면 X/Y로 버튼을 옮기고 메시지를 선택한 뒤 Ctrl+C를 누르세요. 시간 표시가 켜져 있으면 표시된 시간도 함께 복사됩니다. 메시지 도구는 전투 기록을 건드리지 않습니다(전투 기록 자체 설정으로 모든 줄에 시간을 표시할 수 있습니다). 전투 기록 줄도 비활성 흐리기를 깨웁니다. 저장된 기록은 이 캐릭터의 것입니다.")
