T("Turn off Show combat time to hide both the duration in every meter header and the separate floating timer. The two switches below let you show either one independently.", "'전투 시간 표시'를 끄면 모든 측정기 머리글의 지속 시간과 별도의 떠 있는 타이머가 모두 숨겨집니다. 아래 두 스위치로 둘 중 하나만 따로 표시할 수 있습니다.")
