T("Turn the cooldown manager on in Basics to play it.", "재생하려면 기본사항에서 재사용 대기시간 관리자를 켜세요.")
T("Tutorials and help overlays", "튜토리얼 및 도움말 오버레이")
T("Two rows", "두 줄")
T("Two-color material gradients", "2색 재질 그라데이션")
T("Type /keys or /msufkeys to see your own current keystone. Add party, raid or instance to share it in that channel. /keys group requests keys from group members running this Suite helper. The /keys alias is used only when another addon has not claimed it. Inside dungeons and raids Blizzard locks chat for addons; your key is then shown only to you.", "/keys 또는 /msufkeys로 현재 자신의 쐐기돌을 확인합니다. 뒤에 party, raid 또는 instance를 붙이면 해당 채널에 공유합니다. /keys group은 이 Suite 기능을 사용하는 파티원에게 쐐기돌 정보를 요청합니다. /keys 단축 명령은 다른 애드온이 사용하지 않을 때만 등록됩니다. 던전과 공격대 안에서는 블리자드가 애드온의 대화를 막으므로 쐐기돌이 본인에게만 표시됩니다.")
T("Type /msufguildprivacy or use the small ON/OFF button above the main chat window. Any chat window containing Guild or Officer is covered in full, including other channels in a mixed window. Click a cover to reveal the windows again. Messages keep arriving underneath.", "/msufguildprivacy를 입력하거나 기본 대화창 위의 작은 ON/OFF 버튼을 사용하세요. 길드 또는 길드 관리자 채널이 포함된 대화창은 다른 채널이 함께 있어도 창 전체를 가립니다. 가림막을 클릭하면 다시 표시됩니다. 메시지는 가려진 동안에도 계속 수신됩니다.")
T("Type /msufmacro to preview a mouseover ally, mouseover enemy or focus enemy macro. Enter a spell name or ID, then explicitly create a character macro outside combat. Drag it from /macro to your action bar.", "/msufmacro를 입력해 마우스를 올린 아군, 마우스를 올린 적 또는 주시 대상 적을 위한 매크로를 미리 보세요. 주문 이름이나 ID를 입력한 뒤 전투 밖에서 캐릭터 매크로 만들기를 직접 선택합니다. 만든 매크로는 /macro에서 행동 단축바로 끌어 놓으세요.")
T("Type /msufraid to expand Blizzard's Raid Manager, /msufpull [1-60] for its native countdown, or /msufmark tank or /msufmark healer to mark one unambiguous party member. Optional automatic markers work only for one clear tank or healer in a five-player party, as leader or assistant. Existing and occupied markers are respected. Countdowns, markers and ready checks wait while Blizzard restricts them during combat, encounters and keystones; automatic markers try again afterwards.", "블리자드 공격대 관리창은 /msufraid, 기본 초읽기는 /msufpull [1-60], 파티원 한 명의 징표는 /msufmark tank 또는 /msufmark healer를 입력하세요. 자동 징표는 5인 파티에서 탱커 또는 힐러가 정확히 한 명이고 자신이 파티장 또는 부공격대장일 때만 작동합니다. 기존 징표와 사용 중인 징표는 건드리지 않습니다. 전투, 우두머리 전투, 쐐기돌 중 블리자드가 제한하는 동안 초읽기, 징표, 전투 준비 확인은 대기하며, 자동 징표는 그 뒤에 다시 시도합니다.")
T("Type /way x y for the current map or /way mapID x y. /msufway always works. The short /way alias is used only when no other addon owns it.", "현재 지도의 경우 /way x y를 입력하거나 /way mapID x y를 입력하세요. /msufway는 항상 작동합니다. 짧은 /way 별칭은 다른 애드온이 소유하지 않은 경우에만 사용됩니다.")
