T("Uses Blizzard's Sell All Junk action when a merchant opens, including its per-bag exclusions. Hold Shift while opening the merchant to skip selling. The optional chat line confirms the request, not completed sales.", "상인 창을 열면 가방별 제외 설정을 포함해 블리자드의 '잡동사니 모두 판매' 기능을 사용합니다. 상인 창을 열 때 Shift 키를 누르고 있으면 판매를 건너뜁니다. 선택적인 대화창 메시지는 판매 완료가 아니라 요청을 확인해 줍니다.")
