T("Warn when your pet is missing or dead. By default, the missing warning applies to Hunters and Warlocks; the dead warning applies to any class with a pet. MSUF Edit Mode moves the alert.", "소환수가 없거나 죽으면 경고합니다. 기본적으로 소환수 없음 경고는 사냥꾼과 흑마법사에게 적용하고, 사망 경고는 소환수가 있는 모든 직업에 적용합니다. MSUF 편집 모드에서 경고를 옮길 수 있습니다.")
