T("When a ready check starts outside combat and your mana as a healer is low, a short note shows how much you have; it turns red below half of your limit. Only your own mana is read.", "전투 중이 아닐 때 전투 준비 확인이 시작되고 치유 담당인 내 마나가 부족하면, 남은 마나를 짧게 알려 줍니다. 기준의 절반 아래면 빨간색이 됩니다. 내 마나만 확인합니다.")
T("When leaving", "떠날 때")
T("When someone offers you a resurrection, its dialog gets a green frame, optionally with Blizzard's ready check sound, and its accept button can get a green frame of its own. Accepting stays your click.", "누군가 부활을 제안하면 대화 상자에 초록 테두리가 생기고, 원하면 블리자드의 전투 준비 확인 소리도 나며, 수락 버튼에도 따로 초록 테두리를 둘 수 있습니다. 수락은 여전히 직접 클릭해야 합니다.")
T("When the key ends", "쐐기가 끝날 때")
T("When the native group listing panel closes with applications still active, show their count in your own chat. Your applications remain active and no group chat is sent.", "활성 지원이 남은 상태에서 게임 기본 파티 모집 창을 닫으면 자신의 대화창에 지원 건수를 표시합니다. 지원은 그대로 유지되며 파티 채팅에는 아무 메시지도 보내지 않습니다.")
T("When the selected bar appears", "선택한 바 표시 시점")
T("When this bar shows, and how far it fades out of combat. Tooltips show a spell when you hover its icon. This page and MSUF Edit Mode always show every bar.", "이 바가 표시되는 시점과 비전투 중 흐려지는 정도입니다. 아이콘에 마우스를 올리면 툴팁에 주문이 표시됩니다. 이 페이지와 MSUF 편집 모드에서는 항상 모든 바가 표시됩니다.")
T("When to remind", "알림 시점")
T("When to show", "표시 시점")
T("Where", "어디에")
T("Where are the Suite minimap settings?", "Suite 미니맵 설정은 어디에 있나요?")
T("Where are the nameplate settings?", "이름표 설정은 어디에 있나요?")
T("Where is the cooldown manager?", "재사용 대기시간 관리자는 어디에 있나요?")
T("Where the buff or debuff is looked for. Automatic: harmful spells on your target, all others on you.", "강화 효과나 약화 효과를 찾을 위치입니다. 자동: 해로운 주문은 대상에서, 나머지는 자신에게서 찾습니다.")
T("Where to show recent actions", "최근 행동 표시 위치")
T("Which number is drawn on top when both show.", "둘 다 표시될 때 위에 그릴 숫자입니다.")
T("Which numbers show, which one is drawn on top, and their size and place. Single spells can differ: click them in the preview. The font settings below apply to every bar; Slug has no shadow.", "표시할 숫자, 위에 그릴 숫자, 크기와 위치를 정합니다. 주문마다 다르게 설정할 수 있으니 미리보기에서 클릭하세요. 아래 글꼴 설정은 모든 바에 적용되며, Slug에는 그림자가 없습니다.")
T("While DataTexts and this choice are enabled, MSUF remembers this character's gold at login and after money changes. Hover a Gold or Session gold DataText to see the last known account total and up to eight other characters. No background scans are used.", "데이터 텍스트와 이 옵션이 켜져 있으면 로그인 시와 골드 변경 시 이 캐릭터의 골드를 기록합니다. 골드 또는 세션 골드 데이터 텍스트에 마우스를 올리면 마지막으로 확인된 계정 합계와 최대 8명의 다른 캐릭터를 볼 수 있습니다. 백그라운드 검색은 수행하지 않습니다.")
T("While DataTexts is active, hide Blizzard's backpack and bag slots. A Bag space DataText opens the native bags when clicked. Turn this off to restore the Blizzard buttons.", "정보 문자가 활성화된 동안 블리자드의 배낭 및 가방 칸을 숨깁니다. 가방 공간 정보 문자를 클릭하면 기본 가방이 열립니다. 끄면 블리자드 버튼이 복원됩니다.")
T("While a key runs, each defeated boss shows how far ahead or behind you are: against the best time you ever had on that boss, or against the boss times of your fastest completed run, at this keystone level or at any. Only runs this character completed count. With target times on, bosses still alive show the time to beat.", "쐐기 진행 중에는 처치한 각 보스가 얼마나 앞서거나 뒤처졌는지 보여 줍니다. 그 보스의 최고 기록 또는 가장 빨리 완료한 공략의 보스 시간과 비교하며, 현재 단수나 모든 단수를 기준으로 할 수 있습니다. 이 캐릭터가 완료한 공략만 계산합니다. 목표 시간을 켜면 아직 살아 있는 보스에 넘어야 할 시간이 표시됩니다.")
T("While the buff of this spell lasts, the icon shows its duration and stacks instead of the cooldown.", "이 주문의 강화 효과가 지속되는 동안 아이콘에 재사용 대기시간 대신 지속 시간과 중첩이 표시됩니다.")
