T("Wine-black panels with dusty rose controls.", "빛바랜 장밋빛 컨트롤의 와인빛 검정 패널.")
T("WoW Forever only. Lists your group's threat on the watched enemy from Blizzard's threat data, highest first; for a friendly target, its enemy is used. Values the game keeps hidden are left out. Turn the mouse wheel over the window when more members are listed than rows fit. The red mark shows where you would take aggro, which is not the point where you match the tank. The meter repaints at most five times a second and reads no combat log.", "WoW Forever 전용입니다. 블리자드 위협 정보로 지켜보는 적에 대한 그룹 위협을 높은 순으로 표시하며, 아군 대상이면 그 대상의 적을 사용합니다. 게임이 숨기는 값은 빠집니다. 줄보다 많은 구성원이 있으면 창 위에서 마우스 휠을 돌리세요. 빨간 표시는 어그로를 가져올 지점이며, 탱커와 같아지는 지점과는 다릅니다. 측정기는 초당 최대 다섯 번 다시 그리며 전투 기록을 읽지 않습니다.")
